/// #3051: a bad `--argjson`/`--slurpfile`/`--rawfile` argument is jq's own
/// *usage* error (exit 2, a single `jq: ...` line), not the generic
/// `anyhow`-routed exit 1 (`Error: .../Caused by:`) it used to fall through
/// to. Wrapper wording pinned against the live pinned jq 1.7.1 -- exactly,
/// for the file-not-found and `--argjson` rows; the `--slurpfile` malformed-
/// JSON row's own inner detail text is a recorded divergence (see
/// `docs/compliance/jq/limitations.md`), so only its wrapper/exit code is
/// checked there.
#[test]
fn test_bad_argjson_slurpfile_rawfile_exit_2_not_1_3051() -> Result<()> {
    // --argjson: malformed JSON, exit 2, jq's own wording plus usage hint.
    let (stdout, stderr, code) = run_jq_full(&["-nc", "1", "--argjson", "x", "[1,"], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: invalid JSON text passed to --argjson\n\
         Use jq --help for help with command-line options,\n\
         or see the jq manpage, or online docs  at https://jqlang.github.io/jq\n"
    );

    // --slurpfile: missing file, exit 2, byte-identical to jq's own wording.
    let (stdout, stderr, code) =
        run_jq_full(&["-nc", "1", "--slurpfile", "x", "/nonexistent"], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: Bad JSON in --slurpfile x /nonexistent: Could not open /nonexistent: \
         No such file or directory\n"
    );

    // --rawfile: missing file, exit 2, byte-identical to jq's own wording
    // even though a raw file is never actually parsed as JSON -- jq's own
    // generic arg-file reader uses the "Bad JSON in --rawfile" wrapper
    // unconditionally, confirmed live.
    let (stdout, stderr, code) =
        run_jq_full(&["-nc", "1", "--rawfile", "x", "/nonexistent"], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: Bad JSON in --rawfile x /nonexistent: Could not open /nonexistent: \
         No such file or directory\n"
    );

    // --slurpfile: malformed JSON in an existing file, exit 2. Only the
    // wrapper is pinned here (`docs/compliance/jq/limitations.md` records
    // why the inner detail after the second `: ` is succinctly's own).
    let mut file = NamedTempFile::new()?;
    writeln!(file, "{{\"ok\":1}}")?;
    write!(file, "[1,2,")?;
    let path = file.path().to_str().unwrap().to_string();
    let (stdout, stderr, code) = run_jq_full(&["-nc", "1", "--slurpfile", "x", &path], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert!(
        stderr.starts_with(&format!("jq: Bad JSON in --slurpfile x {path}: ")),
        "stderr: {stderr:?}"
    );

    // --rawfile: a file that exists and reads, but isn't valid UTF-8 --
    // `strerror_only`'s `None` arm, the one `std::io::Error` shape with no
    // `" (os error N)"` suffix for it to strip (`ErrorKind::InvalidData` is
    // constructed from a plain string, not an OS errno).
    let mut file = NamedTempFile::new()?;
    file.write_all(&[0xff, 0xfe, b' ', b'x'])?;
    let path = file.path().to_str().unwrap().to_string();
    let (stdout, stderr, code) = run_jq_full(&["-nc", "1", "--rawfile", "x", &path], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        format!("jq: Bad JSON in --rawfile x {path}: Could not open {path}: stream did not contain valid UTF-8\n")
    );

    Ok(())
}

/// #3096: a bad `--jsonargs` value is jq's own usage error, exactly like
/// `--argjson` (#3051): exit 2 with `invalid JSON text passed to --jsonargs`
/// plus the same usage-hint trailer -- not the generic `anyhow` exit-1
/// (`Error: .../Caused by:`) it used to fall through to. Wording pinned
/// against the live pinned jq 1.7.1 (same argv0 substitution the #3051 test
/// above already applies).
#[test]
fn test_bad_jsonargs_exit_2_not_1_3096() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-nc", "1", "--jsonargs", "[1,"], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: invalid JSON text passed to --jsonargs\n\
         Use jq --help for help with command-line options,\n\
         or see the jq manpage, or online docs  at https://jqlang.github.io/jq\n"
    );
    Ok(())
}

/// #3098: an unreadable `-f`/`--from-file` filter file and an unreadable
/// main input file are jq's own usage errors (exit 2) -- not the generic
/// exit-1 `anyhow` route (`Error: .../Caused by:`) each used to take. The
/// two wordings differ from each other (no `error:` prefix or `file` noun
/// for `-f`; both present for the main input) and from `--slurpfile`/
/// `--rawfile`'s own `Bad JSON in --X ...` wrapper (#3051), so each is
/// pinned byte-for-byte against the live pinned jq 1.7.1 separately --
/// both exit codes and both message shapes confirmed live.
#[test]
fn test_bad_from_file_and_main_input_exit_2_not_1_3098() -> Result<()> {
    // -f/--from-file: missing filter file, exit 2.
    let (stdout, stderr, code) = run_jq_full(&["-f", "/nonexistent"], Some("{}"))?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: Could not open /nonexistent: No such file or directory\n"
    );

    // Main input file, plain `.` filter -- the lazy (raw-bytes) path.
    let (stdout, stderr, code) = run_jq_full(&[".", "/nonexistent"], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: error: Could not open file /nonexistent: No such file or directory\n"
    );

    // Main input file through the `inputs` builtin -- the materializing
    // path, which routes the read through `get_inputs` rather than the
    // lazy path's raw-bytes collect, so it exercises the downcast back out
    // of the `anyhow` channel.
    let (stdout, stderr, code) = run_jq_full(&["inputs", "/nonexistent"], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: error: Could not open file /nonexistent: No such file or directory\n"
    );

    // DSV input mode (--input-dsv) routes its main-input read through the
    // same exit-2 path. jq itself has no DSV mode, so there is no oracle
    // for this one -- the wording is succinctly's own, asserted only so a
    // future refactor can't silently route it back to exit 1.
    let (stdout, stderr, code) = run_jq_full(&["--input-dsv", ",", ".", "/nonexistent"], None)?;
    assert_eq!(code, 2, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: error: Could not open file /nonexistent: No such file or directory\n"
    );

    Ok(())
}

// =============================================================================
// #2052: `--argjson`/`--jsonargs` validate through the crate's own RFC 8259
// validator in jq's accept-set (`json::validate::validate_jq_lenient`),
// replacing `serde_json` plus a chain of one text-rewriting normalizer per
// leniency. Every expectation below captured live from `/usr/bin/jq` 1.7.1.
// =============================================================================

/// The whole accept-set, end to end: what the validator admits, the decoder
/// must materialize, and the pair must answer exactly what jq answers.
///
/// This is the guard the design turns on -- a spelling admitted by the
/// validator that the decoder then refuses, or reads differently from jq, is
/// the #1247 "validated, then failed to decode" shape, and the two live in
/// different modules with no compiler-enforced link between them.
///
/// The three `1e400` rows are the behaviour that *changes* with #2052:
/// `serde_json::Value` rejected a magnitude-overflowing literal ("number out
/// of range") and #1095 kept that deliberately, reasoning the value would
/// otherwise materialize as `null`. Neither half still holds -- the decoder
/// preserves the literal, and jq 1.7.1 accepts it -- so the rejection was a
/// divergence carried only by these two flags.
#[test]
fn test_argjson_accept_set_matches_jq_2052() -> Result<()> {
    for (value, expected) in [
        ("007", "7"),
        ("00", "0"),
        ("00.5", "0.5"),
        ("01", "1"),
        ("-01", "-1"),
        ("007e5", "7E+5"),
        ("00e5", "0E+5"),
        (".5", "0.5"),
        ("-.5", "-0.5"),
        (".05", "0.05"),
        (".0", "0.0"),
        (".5e3", "5E+2"),
        ("1.e5", "1E+5"),
        ("1.E5", "1E+5"),
        ("\"\\udc00\"", "\"�\""),
        ("[007,\"\\udc00\",.5,1.e5]", "[7,\"�\",0.5,1E+5]"),
        ("1e400", "1E+400"),
        ("-1e400", "-1E+400"),
        ("1e400000000000", "1.7976931348623157e+308"),
        ("123", "123"),
        ("1.500", "1.500"),
        ("1e100", "1E+100"),
        ("99999999999999999", "99999999999999999"),
        ("0099999999999999999999999", "99999999999999999999999"),
        ("1.0", "1.0"),
        ("[1,2]", "[1,2]"),
        ("{\"a\":[1,{\"b\":.5}]}", "{\"a\":[1,{\"b\":0.5}]}"),
        ("null", "null"),
        ("true", "true"),
        ("\"x\"", "\"x\""),
        ("[]", "[]"),
        ("{}", "{}"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-nc", "--argjson", "x", value, "$x"], None)?;
        assert_eq!(
            code, 0,
            "--argjson {value}: stdout: {stdout:?} stderr: {stderr:?}"
        );
        assert_eq!(stdout.trim_end(), expected, "--argjson {value}");

        // `--jsonargs` shares `parse_json_value`, so the same spelling must
        // reach the same value through the positional-argument route.
        let wrapped = format!("[{expected}]");
        let (stdout, stderr, code) =
            run_jq_full(&["-nc", "$ARGS.positional", "--jsonargs", value], None)?;
        assert_eq!(
            code, 0,
            "--jsonargs {value}: stdout: {stdout:?} stderr: {stderr:?}"
        );
        assert_eq!(stdout.trim_end(), wrapped, "--jsonargs {value}");
    }
    Ok(())
}

/// The reject-set, in three groups with three different reasons.
#[test]
fn test_argjson_reject_set_2052() -> Result<()> {
    // 1. jq rejects these too -- the base grammar is unmoved.
    for value in [
        "\"\\ud800\"",
        "{\"a\":1,}",
        "[1,]",
        "1 2",
        "1e",
        "0x10",
        "'a'",
        "1.2.3",
        "1_000",
        "[,]",
        "{,}",
        "[1 2]",
        "\"abc",
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-nc", "--argjson", "x", value, "$x"], None)?;
        assert_ne!(
            code, 0,
            "--argjson {value}: stdout: {stdout:?} stderr: {stderr:?}"
        );
        assert_eq!(stdout, "", "--argjson {value}");
    }

    // 2. The recorded rule-4c divergence (#2240): jq answers `5`/`7`/`0`, and
    //    this validator refuses on purpose -- admitting a bare trailing dot
    //    would route `99999999999999999.` through `from_number_bytes`'s
    //    large-integer gap. See `docs/compliance/jq/limitations.md`.
    for value in ["5.", "-5.", "[5.]", "{\"a\":5.}", "1.", "0.", "007."] {
        let (stdout, _stderr, code) = run_jq_full(&["-nc", "--argjson", "x", value, "$x"], None)?;
        assert_ne!(code, 0, "rule-4c row must stay rejected: {value}");
        assert_eq!(stdout, "", "{value}");
    }

    // 3. #2877 closed the old third group (`+1`, `nan`, `Infinity`): those
    //    are accepted now, see `test_jq_number_spellings_every_input_path_2877`.
    //    What stays rejected is every way its two gates can fail to fire --
    //    a word that is not decNumber's, a NaN with anything but digits
    //    after it, a `+` before anything but a digit, `.` or such a word --
    //    each captured as `Invalid numeric literal` from jq 1.7.1, plus the
    //    rule-4c refusal with a `+` in front.
    for value in [
        "nanx",
        "nana",
        "nan.",
        "nan1.5",
        "nan1e3",
        "nan-1",
        "nan(1)",
        "qnan",
        "ssnan",
        "infin",
        "Infinite",
        "infinity1",
        "inf1",
        "sinf",
        "infx",
        "1nan",
        "+",
        "++1",
        "+-1",
        "-+1",
        "+ 1",
        "+e5",
        "+0x10",
        "[nanx]",
        "[+]",
        "{nan:1}",
        "[nan1.5,2]",
        "+5.",
        "+007.",
        "+9e999e999",
        "+1e0e0",
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["-nc", "--argjson", "x", value, "$x"], None)?;
        assert_ne!(code, 0, "--argjson must reject: {value}");
        assert_eq!(stdout, "", "{value}");
    }
    Ok(())
}

// =============================================================================
// #2877: jq 1.7.1 reads numbers with decNumber's grammar, so a leading `+`
// (`+1`, `+.5`, `+1.500`) and the special values (`nan`, `NaN5`, `sNaN`,
// `inf`, `Infinity`, signed or not, any case) are numbers on every input
// path. Every expectation below was captured live from `/usr/bin/jq` 1.7.1;
// a NaN is a real number there (`type` is `"number"`, `isnan` is `true`) and
// only *prints* as `null`, an infinity is a real `f64` infinity clamped to
// `DBL_MAX` text at print time, and `+X` prints exactly as `X`.
// =============================================================================

/// The spelling matrix, on every path a number can enter: the primary
/// document (top-level and nested, on the raw-echo, cursor, materializing
/// and `--slurp` routes), `-n input`, `--argjson`, `--jsonargs`,
/// `--slurpfile` and `--seq`. `fromjson` uses the same accept-set as of #3032;
/// its focused spelling and error tests are below.
#[test]
fn test_jq_number_spellings_every_input_path_2877() -> Result<()> {
    // (spelling, jq's printed form)
    let rows: &[(&str, &str)] = &[
        ("+1", "1"),
        ("+0", "0"),
        ("+01", "1"),
        ("+.5", "0.5"),
        ("+1.500", "1.500"),
        ("+1e400", "1E+400"),
        ("+1.e5", "1E+5"),
        ("+.5e3", "5E+2"),
        ("+007.e5", "7E+5"),
        ("nan", "null"),
        ("NaN", "null"),
        ("nAn", "null"),
        ("-nan", "null"),
        ("+nan", "null"),
        ("nan1", "null"),
        ("nan0012", "null"),
        ("sNaN", "null"),
        ("SNAN12", "null"),
        ("-sNaN", "null"),
        ("inf", "1.7976931348623157e+308"),
        ("INF", "1.7976931348623157e+308"),
        ("Infinity", "1.7976931348623157e+308"),
        ("iNfInItY", "1.7976931348623157e+308"),
        ("+inf", "1.7976931348623157e+308"),
        ("-inf", "-1.7976931348623157e+308"),
        ("-Infinity", "-1.7976931348623157e+308"),
    ];
    for &(spelling, printed) in rows {
        let nested = format!("[{spelling},2]");
        let nested_out = format!("[{printed},2]");
        let object = format!(r#"{{"a":{spelling}}}"#);
        let object_out = format!(r#"{{"a":{printed}}}"#);

        // Primary input: top-level, on the raw-echo (`.`), compact
        // (`-c .`), cursor (`.[0]`), materializing (`map(.)`) and
        // `--slurp` routes; nested in an array and in an object.
        for (args, input, expected) in [
            (vec!["-c", "."], spelling.to_string(), printed.to_string()),
            (vec!["."], spelling.to_string(), printed.to_string()),
            (vec!["-c", "."], nested.clone(), nested_out.clone()),
            (vec!["-c", "map(.)"], nested.clone(), nested_out.clone()),
            (vec!["-c", ".[0]"], nested.clone(), printed.to_string()),
            (vec!["-c", "."], object.clone(), object_out.clone()),
            (vec!["-c", ".a"], object.clone(), printed.to_string()),
            (
                vec!["-c", "-s", "."],
                nested.clone(),
                format!("[{nested_out}]"),
            ),
            (
                vec!["-c", "-s", ".[0][0]"],
                nested.clone(),
                printed.to_string(),
            ),
            (vec!["-nc", "input"], nested.clone(), nested_out.clone()),
            (
                vec!["-nc", "[inputs]"],
                format!("{spelling}\n{spelling}"),
                format!("[{printed},{printed}]"),
            ),
        ] {
            let (stdout, stderr, code) = run_jq_full(&args, Some(&input))?;
            assert_eq!(code, 0, "{args:?} on {input:?}: stderr: {stderr:?}");
            assert_eq!(stdout.trim_end(), expected, "{args:?} on {input:?}");
        }

        // `--argjson` / `--jsonargs`, top-level and nested.
        for (value, expected) in [
            (spelling, printed.to_string()),
            (nested.as_str(), nested_out.clone()),
        ] {
            let (stdout, stderr, code) =
                run_jq_full(&["-nc", "--argjson", "x", value, "$x"], None)?;
            assert_eq!(code, 0, "--argjson {value}: stderr: {stderr:?}");
            assert_eq!(stdout.trim_end(), expected, "--argjson {value}");
            let (stdout, stderr, code) =
                run_jq_full(&["-nc", "$ARGS.positional", "--jsonargs", value], None)?;
            assert_eq!(code, 0, "--jsonargs {value}: stderr: {stderr:?}");
            assert_eq!(
                stdout.trim_end(),
                format!("[{expected}]"),
                "--jsonargs {value}"
            );
        }

        // `--slurpfile`: one top-level value per line.
        let mut file = NamedTempFile::new()?;
        writeln!(file, "{spelling}")?;
        writeln!(file, "{nested}")?;
        let path = file.path().to_str().unwrap().to_string();
        let (stdout, stderr, code) = run_jq_full(&["-nc", "--slurpfile", "s", &path, "$s"], None)?;
        assert_eq!(code, 0, "--slurpfile {spelling}: stderr: {stderr:?}");
        assert_eq!(
            stdout.trim_end(),
            format!("[{printed},{nested_out}]"),
            "--slurpfile {spelling}"
        );

        // `--seq`: the reader's grammar already accepted these tokens and
        // then dropped the record when materialization failed (#2877's
        // "no output, no warning, exit 0" row); now it prints them.
        let input = format!("\u{1e}{nested}\n");
        let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(&input))?;
        assert_eq!(code, 0, "--seq {nested}: stderr: {stderr:?}");
        assert_eq!(
            stdout.trim_end(),
            format!("\u{1e}{nested_out}"),
            "--seq {nested}"
        );
        assert_eq!(stderr, "", "--seq {nested} must not warn");
    }
    Ok(())
}

/// #3034: document text spelled like one of the reindex bridge's number
/// tokens (`9e999e999` = NaN, `8e999e999` = Infinity, `1e0e0` = the computed
/// float `1`) used to decode as the value the token stands for. jq 1.7.1
/// rejects every one of these documents (`Invalid numeric literal`, exit 5),
/// as it rejects every malformed nested number; succinctly reads each
/// malformed nested number the same way instead (#966's uniform divergence,
/// ADR-0018's #2103 amendment). A token is only a token in text the bridge
/// wrote, so each row must behave exactly like its nearest non-token
/// sibling spelling, on every route.
///
/// Output is compared with the token's spelling substituted by the
/// sibling's, so a route that echoes the source text (`--preserve-input`)
/// compares equal too.
#[test]
fn test_bridge_token_spellings_read_like_their_siblings_3034() -> Result<()> {
    // (bridge-token spelling, a malformed sibling that is not a token)
    let pairs: &[(&str, &str)] = &[
        ("9e999e999", "9e999e998"),
        ("-9e999e999", "-9e999e998"),
        ("8e999e999", "8e999e998"),
        ("-8e999e999", "-8e999e998"),
        ("1e0e0", "1e0e1"),
        ("2.5e0e0", "2.5e0e1"),
        ("-1e0e0", "-1e0e1"),
        ("1.2345e-7e0", "1.2345e-7e1"),
    ];
    for &(token, sibling) in pairs {
        for (wrap, at) in [("[{}]", ".[0]"), (r#"{"a":{}}"#, ".a")] {
            let doc = |n: &str| wrap.replace("{}", n);
            let scalar = |f: &str| format!("{at} | {f}");
            let filters: Vec<(Vec<&str>, String)> = [
                (vec!["-c"], ".".to_string()),
                (vec!["-c"], "map(.)".to_string()),
                (vec!["-c"], at.to_string()),
                (vec!["-c"], "[.[]]".to_string()),
                (vec!["-c"], scalar("[isnan, isinfinite, isnormal]")),
                (vec!["-c"], scalar("length")),
                (vec!["-c"], scalar("tostring")),
                (vec!["-c"], scalar(". + 0")),
                (vec!["-c"], scalar("type")),
                (vec!["-c"], scalar("todate")),
                (vec!["-c"], "tojson".to_string()),
                (vec!["-c"], "reduce .[] as $x (0; $x)".to_string()),
                (vec!["-c"], ". as $x | $x".to_string()),
                (vec!["-c"], "getpath([0]), getpath([\"a\"])".to_string()),
                (vec!["-c"], "with_entries(.)".to_string()),
                (vec!["-c", "-s"], ".".to_string()),
                (vec!["-c", "-s"], format!(".[0] | {at}")),
                (vec!["-c", "-n"], "input".to_string()),
                (vec!["-c", "-n"], "[inputs]".to_string()),
                (vec!["-c", "-S"], ".".to_string()),
                (vec!["-c", "-a"], ".".to_string()),
                (vec!["-c", "--preserve-input"], ".".to_string()),
            ]
            .into_iter()
            .collect();
            for (flags, filter) in &filters {
                let mut args = flags.clone();
                args.push(filter);
                let got = run_jq_full(&args, Some(&doc(token)))?;
                let want = run_jq_full(&args, Some(&doc(sibling)))?;
                let got = (
                    got.0.replace(token, sibling),
                    got.1.replace(token, sibling),
                    got.2,
                );
                assert_eq!(got, want, "{args:?} on {} vs {}", doc(token), doc(sibling));
            }

            // `--slurpfile`: the file's values are read, then bound.
            let mut outputs = Vec::new();
            for n in [token, sibling] {
                let mut file = NamedTempFile::new()?;
                writeln!(file, "{}", doc(n))?;
                let path = file.path().to_str().unwrap().to_string();
                let (stdout, _, code) =
                    run_jq_full(&["-nc", "--slurpfile", "s", &path, "$s"], None)?;
                outputs.push((stdout.replace(token, sibling), code));
            }
            assert_eq!(outputs[0], outputs[1], "--slurpfile {}", doc(token));
        }
    }
    Ok(())
}

/// #3034's other half: the bridge's own tokens still decode on every route
/// that reindexes a computed value, so a NaN, an infinity and a computed
/// float survive the round trip. Values captured from jq 1.7.1.
#[test]
fn test_bridge_tokens_still_round_trip_computed_values_3034() -> Result<()> {
    for (filter, expected) in [
        (
            "[nan, infinite, -infinite, 0.5 + 0.25]",
            "[null,1.7976931348623157e+308,-1.7976931348623157e+308,0.75]",
        ),
        (
            "[nan, infinite, 0.5 + 0.25] | map(isnan)",
            "[true,false,false]",
        ),
        (
            "[nan, infinite, 0.5 + 0.25] | map(isinfinite)",
            "[false,true,false]",
        ),
        (
            "reduce (nan, infinite, 0.5 + 0.25) as $x ([]; . + [$x]) | map(isnan, isinfinite)",
            "[true,false,false,true,false,false]",
        ),
        (
            "{a: nan, b: infinite} | with_entries(.) | map_values(isnan)",
            r#"{"a":true,"b":false}"#,
        ),
        (
            "[nan, -infinite] | . as $x | $x | map(length)",
            "[null,1.7976931348623157e+308]",
        ),
    ] {
        assert_eq!(
            run_jq_full(&["-nc", filter], None)?,
            (format!("{expected}\n"), String::new(), 0),
            "{filter}"
        );
    }
    // The `--slurp` input path writes the same tokens for a document `nan`/
    // `Infinity` (#2877) and must keep reading them back.
    assert_eq!(
        run_jq_full(
            &["-c", "-s", ". , map(map(isnan))"],
            Some("[nan, Infinity]")
        )?,
        (
            "[[null,1.7976931348623157e+308]]\n[[true,false]]\n".into(),
            String::new(),
            0
        )
    );
    Ok(())
}

/// The builtins see the *value*, not the printed form: a document `nan` is a
/// number that `isnan`, an `Infinity` a number that `isinfinite`, and
/// `+1.50` keeps its spelling for display while computing as `1.5`. Rows
/// captured from jq 1.7.1 on the same documents; each is run on the cursor
/// route and, through `--slurp`, on the reindexed materializing route.
#[test]
fn test_jq_number_spellings_builtins_2877() -> Result<()> {
    for (input, filter, expected) in [
        (
            "[SNAN,+Infinity,NaN5,-Inf,+.5e1,+1.50,-snan00]",
            "., map(type)",
            "[null,1.7976931348623157e+308,null,-1.7976931348623157e+308,5,1.50,null]\n\
             [\"number\",\"number\",\"number\",\"number\",\"number\",\"number\",\"number\"]",
        ),
        (
            "[nan]",
            ".[0] | [type, isnan, isinfinite, isnormal, tostring, tojson, length, (. < .), (. + 0), (. + 1 | isnan), (. == 1)]",
            "[\"number\",true,false,false,\"null\",\"null\",null,true,null,true,false]",
        ),
        (
            "[nan, NaN]",
            "[(.[0] == .[1]), sort, unique, (group_by(.) | length), (map(isnan) | all)]",
            "[false,[null,null],[null,null],2,true]",
        ),
        (
            "[Infinity, -inf]",
            "[.[0] | type, isinfinite, (. == 1.7976931348623157e+308), tostring, tojson, length, (. + 1)], [.[1] | tostring, (. - 1)], sort, (.[0] > .[1])",
            "[\"number\",true,false,\"1.7976931348623157e+308\",\"1.7976931348623157e+308\",1.7976931348623157e+308,1.7976931348623157e+308]\n\
             [\"-1.7976931348623157e+308\",-1.7976931348623157e+308]\n\
             [-1.7976931348623157e+308,1.7976931348623157e+308]\n\
             true",
        ),
        (
            "+1.50",
            "[., tostring, .+0, length, tojson, type, (. == 1.5)]",
            "[1.50,\"1.50\",1.5,1.5,\"1.50\",\"number\",true]",
        ),
        (
            r#"{"a":+007,"b":nan}"#,
            ".,(.a|type),(.b|type),to_entries,[tostream],keys,[.[]],(.a|=.+1),del(.b)",
            "{\"a\":7,\"b\":null}\n\"number\"\n\"number\"\n[{\"key\":\"a\",\"value\":7},{\"key\":\"b\",\"value\":null}]\n\
             [[[\"a\"],7],[[\"b\"],null],[[\"b\"]]]\n[\"a\",\"b\"]\n[7,null]\n{\"a\":8,\"b\":null}\n{\"a\":7}",
        ),
        // `-e`: a NaN is truthy, as every number is.
        ("[nan]", ".[0]", "null"),
    ] {
        for extra in [&[][..], &["-s", "--argjson", "unused", "0"][..]] {
            let filter = if extra.is_empty() {
                filter.to_string()
            } else {
                format!(".[0] | {filter}")
            };
            let mut args = vec!["-c", "-e"];
            args.extend_from_slice(extra);
            args.push(&filter);
            let (stdout, stderr, code) = run_jq_full(&args, Some(input))?;
            assert_eq!(code, 0, "{args:?} on {input}: stderr {stderr:?}");
            let expected: String = expected
                .lines()
                .map(str::trim_start)
                .collect::<Vec<_>>()
                .join("\n");
            assert_eq!(stdout.trim_end(), expected, "{args:?} on {input}");
        }
    }
    Ok(())
}

/// Every way the two #2877 gates can fail to fire keeps erroring on the
/// document path, matching jq's `Invalid numeric literal` (exit 5): a word
/// that is not decNumber's, a NaN followed by anything but digits, a `+`
/// before anything but a digit, `.` or such a word -- and the whole scalar
/// token has to validate, so `nan1.5` is not read as `nan1` plus leftovers.
/// The bridge's own tokens with a `+` in front are user text and read like
/// `+1.2.3` (raising since #3222), never as a NaN or an infinity.
///
/// Asserted as "does not become a number" on the materializing route as
/// well as "errors" on the identity route: #3035's pre-existing keyword
/// prefix match means a *neighbouring* row (`nullx`) does not error today,
/// so "errors" alone would be the wrong shape for a gate this close to it.
#[test]
fn test_jq_number_spellings_reject_set_2877() -> Result<()> {
    for token in [
        "nana",
        "nanx",
        "nan.",
        "nan1.5",
        "nan1e3",
        "nan-1",
        "nan(1)",
        "qnan",
        "ssnan",
        "nA",
        "infin",
        "infinit",
        "Infinite",
        "infinity1",
        "inf1",
        "sinf",
        "infx",
        "infinityx",
        "+",
        "+x",
        "+e5",
        "++1",
        "+-1",
        "+nanx",
        "+infx",
        "snan.",
    ] {
        for input in [
            format!("[{token}]"),
            format!("[{token},2]"),
            format!(r#"{{"a":{token}}}"#),
            token.to_string(),
        ] {
            for filter in ["-c .", "-c map(.)", "-c [.[]]"] {
                if !input.starts_with(['[', '{']) && filter != "-c ." {
                    continue;
                }
                let args: Vec<&str> = filter.split(' ').collect();
                let (stdout, _stderr, code) = run_jq_full(&args, Some(&input))?;
                assert_eq!(
                    code, 5,
                    "{filter:?} on {input:?} must be a parse error, got {stdout:?}"
                );
                assert!(
                    !stdout.contains("null") && !stdout.contains("e+308"),
                    "{filter:?} on {input:?} materialized a number: {stdout:?}"
                );
            }
        }
    }
    // `{nan:1}`: a key must be a string.
    let (_, _, code) = run_jq_full(&["-c", "."], Some("{nan:1}"))?;
    assert_eq!(code, 5);
    // A digit-led token with letters after it (`1nan`), and a `-`-led one
    // that is not a decNumber word (`-snan.`, `-nope`): the identity route
    // rejects both (the #1643 gap check), but the materializing route reads
    // the `1` / the bare `-` and drops the rest -- exactly as `[1abc]` and
    // `[-nope]` do today and did before #2877 (`-` was never this issue's
    // arm). That is #3035's shape (a scalar's trailing bytes go unread),
    // not a word gate of this issue's, so only the identity half is pinned.
    // `+0x10` is the same shape: `+X` is `X`, and `[0x10] | map(.)` is `[0]`
    // today for the same reason.
    for input in ["[1nan]", "[-snan.]", "[-nope]", "[+0x10]", "[0x10]"] {
        let (stdout, _, code) = run_jq_full(&["-c", "."], Some(input))?;
        assert_eq!(code, 5, "{input}: {stdout:?}");
    }
    // A `+` in front of the bridge's tokens, or of a malformed span, reads
    // exactly as the unsigned spelling does: a malformed number, raised
    // when read (#3222; #966's `null` before that), never a NaN, an
    // infinity or a computed float.
    for input in [
        "[+9e999e999]",
        "[+8e999e999]",
        "[+1e0e0]",
        "[+1.2.3]",
        "[1.2.3]",
        // `-` before anything is the old number-shaped span (#966), so a
        // doubled sign led by `-` is a malformed number, while `+-1` above
        // is not number-shaped at all: `+` is admitted only before a digit,
        // `.` or a decNumber word.
        "[-+1]",
    ] {
        for filter in ["map(.)", ".[0] | [isnan, isinfinite]"] {
            let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
            assert_eq!(code, 5, "{filter} on {input}: {stdout:?}");
            assert_eq!(stdout, "", "{filter} on {input} must not decode");
            assert!(
                stderr.contains("invalid numeric literal"),
                "{input}: {stderr}"
            );
        }
    }
    Ok(())
}

/// The widening is jq's accept-set only: strict RFC 8259 validation --
/// `json validate`, `--validate`, and the library's `validate()` behind
/// them -- still rejects every one of the new spellings.
#[test]
fn test_jq_number_spellings_do_not_leak_into_strict_validation_2877() -> Result<()> {
    for input in [
        "+1",
        "[+1]",
        "nan",
        "[nan]",
        "Infinity",
        r#"{"a":-inf}"#,
        "sNaN12",
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--validate", "-c", "."], Some(input))?;
        assert_ne!(code, 0, "--validate must reject {input:?}");
        assert_eq!(stdout, "", "{input:?}");
        let (output, code) = spawn_with_signal_retry(
            || {
                let mut command = Command::new(succinctly_bin());
                command.args(["json", "validate", "--quiet"]);
                command
            },
            Some(input.as_bytes()),
        )?;
        assert_ne!(code, 0, "json validate must reject {input:?}: {output:?}");
    }
    Ok(())
}

/// `--preserve-input` (a succinctly extension, no oracle) echoes the source
/// spelling verbatim, as it already does for `007` and `.5` -- pinned so it
/// is a decision, not an accident.
#[test]
fn test_jq_number_spellings_preserve_input_echoes_verbatim_2877() -> Result<()> {
    let input = "[nan,+1,Infinity,007,.5]";
    let (stdout, _stderr, code) = run_jq_full(&["--preserve-input", "-c", "."], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), input);
    Ok(())
}

/// `tonumber` reads the same grammar (#2877): the two words Rust's parser
/// lacks are numbers in jq mode, printed as jq prints a NaN.
#[test]
fn test_tonumber_reads_decnumber_specials_2877() -> Result<()> {
    for (input, expected) in [
        (r#""sNaN""#, "null"),
        (r#""nan12""#, "null"),
        (r#""-sNaN00""#, "null"),
        (r#""NaN""#, "null"),
        (r#""Infinity""#, "1.7976931348623157e+308"),
        (r#""+1.500""#, "1.500"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", "tonumber"], Some(input))?;
        assert_eq!(code, 0, "{input}: {stderr:?}");
        assert_eq!(stdout.trim_end(), expected, "{input}");
    }
    let (stdout, _stderr, code) = run_jq_full(
        &["-c", ".[0] | tonumber | [type, isnan]"],
        Some(r#"["sNaN"]"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#"["number",true]"#);
    for input in [r#""nanx""#, r#""nan1.5""#, r#""inf1""#, r#""+-1""#] {
        let (stdout, stderr, code) = run_jq_full(&["-c", "tonumber"], Some(input))?;
        assert_eq!(code, 5, "{input}: {stdout:?}");
        assert!(
            stderr.contains("Invalid numeric literal"),
            "{input}: {stderr:?}"
        );
    }
    Ok(())
}

/// `--seq`'s own gate (`seq_value_is_valid`) shares the same validator, so a
/// record spelling jq accepts is accepted here too -- previously via the same
/// normalizer chain, now from the accept-set directly.
#[test]
fn test_seq_record_leniencies_after_2052() -> Result<()> {
    for (record, expected) in [
        ("007", "7"),
        (".5", "0.5"),
        ("1.e5", "1E+5"),
        ("1e400", "1E+400"),
    ] {
        let input = format!("\u{1e}{record}\n");
        let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(&input))?;
        assert_eq!(
            code, 0,
            "--seq {record}: stdout: {stdout:?} stderr: {stderr:?}"
        );
        // `--seq` output carries RFC 7464's own leading RS byte.
        assert_eq!(
            stdout.trim_end(),
            format!("\u{1e}{expected}"),
            "--seq {record}"
        );
    }

    // The lone low surrogate, kept separate so the expectation can be the
    // real replacement character rather than an escape inside an escape.
    let input = "\u{1e}\"\\udc00\"\n";
    let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout.trim_end(), "\u{1e}\"\u{fffd}\"");
    Ok(())
}

// =============================================================================
// #1094: `--argjson` tolerates a leading-zero number the way real jq's own
// number parser does, instead of rejecting it outright via strict RFC 8259
// validation. All cases live-verified against jq 1.7.1.
// =============================================================================

/// The issue's own repro: a leading-zero integer/float, accepted and
/// normalized exactly like real jq.
#[test]
fn test_argjson_tolerates_leading_zero_number_1094() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", "007", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "7");

    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", "00", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "0");

    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", "007.5", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "7.5");
    Ok(())
}

/// A leading-zero number combined with a *trailing* zero (`007.500`) is
/// accepted (not rejected outright, this issue's own scope) and, since
/// #1149, also keeps the trailing zero's spelling (`7.500`, matching real
/// jq) rather than losing it (`7.5`) the way this crate's own
/// `NumberLiteral`-preservation fast path used to for any leading-zero
/// literal -- same fix (`OwnedValue::from_number_bytes` /
/// `DocumentValue::number_literal`) as the sibling scientific-notation
/// case below, since it's one root cause, broader than #1149's own title
/// suggested.
#[test]
fn test_argjson_leading_zero_accepted_and_trailing_zero_spelling_preserved_1149() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", "007.500", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "7.500");
    Ok(())
}

/// Trailing garbage after a leading-zero number is still rejected --
/// leading-zero tolerance must not accidentally widen the #284 guard it
/// sits next to.
#[test]
fn test_argjson_leading_zero_still_rejects_trailing_garbage_1094() -> Result<()> {
    let (_, _, code) = run_jq_full(&["-n", "--argjson", "n", "007 garbage", "$n"], None)?;
    assert_ne!(code, 0);
    Ok(())
}

/// Plain trailing garbage (no leading zero involved at all) is still
/// rejected -- confirms the fast, common-case path (no normalization
/// needed) is unaffected by this fix.
#[test]
fn test_argjson_plain_trailing_garbage_still_rejected_1094() -> Result<()> {
    let (_, _, code) = run_jq_full(&["-n", "--argjson", "n", "42 garbage", "$n"], None)?;
    assert_ne!(code, 0);
    Ok(())
}

/// A leading-zero number nested inside an array or object is tolerated
/// too, not just a bare top-level scalar.
#[test]
fn test_argjson_leading_zero_tolerated_when_nested_1094() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-cn", "--argjson", "n", "[007, 1]", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "[7,1]");

    let (stdout, _, code) = run_jq_full(&["-cn", "--argjson", "n", r#"{"a": 007}"#, "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#"{"a":7}"#);
    Ok(())
}

/// Digits that merely *look* like a leading-zero number, but are actually
/// inside a string (a value or an object key), are left completely
/// untouched by the normalization pass.
#[test]
fn test_argjson_leading_zero_inside_string_or_key_untouched_1094() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", r#""007""#, "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#""007""#);

    let (stdout, _, code) = run_jq_full(&["-cn", "--argjson", "n", r#"{"007": 1}"#, "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#"{"007":1}"#);
    Ok(())
}

/// A normal number with no leading zero is completely unaffected --
/// confirms the fast path (strict validation succeeds on the first try,
/// no normalization attempted) isn't disturbed by this fix.
#[test]
fn test_argjson_normal_number_unaffected_1094() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", "42", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "42");
    Ok(())
}

/// Genuinely malformed JSON (not just a leading zero) is still rejected --
/// normalization doesn't accidentally make garbage input parse.
#[test]
fn test_argjson_malformed_json_still_rejected_1094() -> Result<()> {
    let (_, _, code) = run_jq_full(&["-n", "--argjson", "n", "not json", "$n"], None)?;
    assert_ne!(code, 0);
    Ok(())
}

/// Regression guard (found by review before merge): a bare `-` with no
/// digit following it isn't a number token at all, but an earlier draft
/// of `normalize_leading_zero_numbers` fabricated a `0` digit for it
/// (turning the genuinely invalid `-` into the valid number `-0`), which
/// made the retried validation wrongly pass and let this malformed input
/// silently reach materialization as `null` instead of erroring. Real jq
/// rejects all three of these outright.
#[test]
fn test_argjson_bare_hyphen_rejected_not_fabricated_into_negative_zero_1094() -> Result<()> {
    let (_, _, code) = run_jq_full(&["-n", "--argjson", "n", "-", "$n"], None)?;
    assert_ne!(code, 0);

    let (_, _, code) = run_jq_full(&["-cn", "--argjson", "n", "[-,1]", "$n"], None)?;
    assert_ne!(code, 0);

    let (_, _, code) = run_jq_full(&["-cn", "--argjson", "n", r#"{"a":-}"#, "$n"], None)?;
    assert_ne!(code, 0);
    Ok(())
}

/// A negative leading-zero number, nested inside an array -- exercises
/// `normalize_leading_zero_numbers`'s own leading-`-` handling. Nesting
/// was originally required to route around #1150's separate CLI
/// arg-parsing bug (a bare negative `--argjson` value was rejected before
/// `normalize_leading_zero_numbers` ever ran); #1150's own fix means the
/// bare form is now directly testable too, see
/// `test_argjson_bare_negative_leading_zero_1150` below.
#[test]
fn test_argjson_negative_leading_zero_when_nested_1094() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-cn", "--argjson", "n", "[-007, 1]", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "[-7,1]");
    Ok(())
}

// -----------------------------------------------------------------------
// #2240 (Gap 2): `--argjson`/`--jsonargs` now tolerate the same
// leading-dot (`.5`, #1171) and trailing-dot-*before-exponent* (`1.e5`,
// #2220) leniencies real jq's own number parser already accepts, via a
// new `normalize_dot_leniency` sibling to `normalize_leading_zero_numbers`
// (both composed together in `normalize_json_leniently`). All cases
// live-verified against jq 1.7.1.
//
// Deliberately **not** a bare trailing `.` with no exponent (`1.`) --
// `normalize_dot_leniency`'s own doc comment explains why: accepting it
// would route to `number_literal()`/`from_number_bytes`'s shared,
// pre-existing large-integer-precision bug (confirmed live via plain
// document input too, not something added or fixed by this issue),
// trading a clean rejection for a silently wrong value. `1.` stays
// rejected via `--argjson`, matching pre-#2240 behavior exactly.
// -----------------------------------------------------------------------

/// The issue's own leading-dot repro, positive and negative, plus values
/// exercising `number_literal()`'s own new leading-dot escape
/// (`src/json/light.rs`) with real precision/formatting at stake --
/// code review found a first draft accepted these via `--argjson`'s
/// validation retry but then silently lost precision materializing them
/// through the *original* (un-normalized) text, since only
/// `OwnedValue::from_number_bytes` had the matching escape at the time,
/// not `number_literal()` (the generic evaluator's own materializer,
/// which `--argjson` reaches).
#[test]
fn test_argjson_tolerates_leading_dot_2240() -> Result<()> {
    for (value, expected) in [
        (".5", "0.5"),
        ("-.5", "-0.5"),
        (".9999999999999999999999", "0.9999999999999999999999"),
        (".100", "0.100"),
        (".0", "0.0"),
    ] {
        let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", value, "$n"], None)?;
        assert_eq!(code, 0, "value {value:?}");
        assert_eq!(stdout.trim_end(), expected, "value {value:?}");
    }
    Ok(())
}

/// The issue's own trailing-dot-before-exponent repro, plus the
/// signed-exponent variant. The bare (no-exponent) form is covered
/// separately below, since it's deliberately still rejected.
#[test]
fn test_argjson_tolerates_trailing_dot_before_exponent_2240() -> Result<()> {
    for (value, expected) in [("1.e5", "1E+5"), ("-1.e5", "-1E+5"), ("1.e-5", "0.00001")] {
        let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", value, "$n"], None)?;
        assert_eq!(code, 0, "value {value:?}");
        assert_eq!(stdout.trim_end(), expected, "value {value:?}");
    }
    Ok(())
}

/// Regression guard (found by review before merge, round 2): a bare
/// trailing `.` with no exponent at all is deliberately *not* accepted by
/// this fix, unlike an earlier draft that treated it the same as the
/// exponent-adjacent form -- see `normalize_dot_leniency`'s own doc
/// comment for the precision-loss reasoning. Real jq itself *does* accept
/// `1.` (giving `1`), so this is a known, deliberate, narrower-than-jq
/// divergence, not a match -- pinned here as the accepted trade-off
/// rather than left as an unstated side effect of the narrowing.
#[test]
fn test_argjson_bare_trailing_dot_still_rejected_2240() -> Result<()> {
    for value in ["1.", "99999999999999999."] {
        let (_, _, code) = run_jq_full(&["-n", "--argjson", "n", value, "$n"], None)?;
        assert_ne!(code, 0, "value {value:?}");
    }
    Ok(())
}

/// A value needing *both* the leading-zero (#1094) and trailing-dot
/// (#2240) leniency at once, the same "needs more than one normalizer"
/// shape #2012's own review caught for the leading-zero/low-surrogate
/// pair -- confirms the three normalizers still compose correctly now
/// that there are three of them.
#[test]
fn test_argjson_leading_zero_and_trailing_dot_combined_2240() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", "007.e5", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "7E+5");
    Ok(())
}

/// A leading/trailing dot leniency nested inside an array, not just a
/// bare top-level scalar -- mirrors `test_argjson_leading_zero_tolerated_when_nested_1094`.
#[test]
fn test_argjson_dot_leniency_tolerated_when_nested_2240() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-cn", "--argjson", "n", "[.5, 1.e5]", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "[0.5,1E+5]");
    Ok(())
}

/// Regression guard (found by review before merge): a bare `.` or `-.`
/// with digits on *neither* side is not a number under any leniency --
/// real jq still rejects it outright, and an earlier draft here
/// unconditionally synthesized `0`s around whatever dot it saw, which
/// wrongly "fixed" a bare `.` into the valid number `0.0` and let this
/// genuinely malformed input silently materialize instead of erroring.
#[test]
fn test_argjson_bare_dot_rejected_not_fabricated_into_zero_2240() -> Result<()> {
    for value in [".", "-."] {
        let (_, _, code) = run_jq_full(&["-n", "--argjson", "n", value, "$n"], None)?;
        assert_ne!(code, 0, "value {value:?}");
    }
    Ok(())
}

/// Digits that merely *look* like a leading/trailing-dot number, but are
/// actually inside a string, are left completely untouched -- mirrors
/// `test_argjson_leading_zero_inside_string_or_key_untouched_1094`.
#[test]
fn test_argjson_dot_leniency_inside_string_untouched_2240() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", r#""a.5b""#, "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#""a.5b""#);
    Ok(())
}

/// A normal number with no leading/trailing dot at all is completely
/// unaffected -- confirms the fast path (strict validation succeeds on
/// the first try) isn't disturbed by this fix.
#[test]
fn test_argjson_normal_number_unaffected_by_dot_leniency_2240() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", "1.5", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "1.5");
    Ok(())
}

// --- #1150: clap rejected any negative-number (or other hyphen-prefixed)
// --argjson/--arg/--slurpfile/--rawfile VALUE before it ever reached this
// crate's own JSON-content validation -- fixed via `allow_hyphen_values`
// on all six affected clap::Arg sites (JqCommand's arg/argjson/slurpfile/
// rawfile, YqCommand's arg/argjson). Verified live against real jq 1.7.1.

#[test]
fn test_argjson_bare_hyphen_prefixed_value_1150() -> Result<()> {
    for (value, expected) in [("-7", "-7"), ("-007", "-7")] {
        let (stdout, _, code) = run_jq_full(&["-n", "--argjson", "n", value, "$n"], None)?;
        assert_eq!(code, 0, "value {value:?}");
        assert_eq!(stdout.trim_end(), expected, "value {value:?}");
    }
    Ok(())
}

#[test]
fn test_arg_hyphen_prefixed_string_value_1150() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "--arg", "n", "-hello", "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#""-hello""#);
    Ok(())
}

#[test]
fn test_multiple_argjson_one_negative_one_positive_1150() -> Result<()> {
    let (stdout, _, code) = run_jq_full(
        &[
            "-cn",
            "--argjson",
            "a",
            "1",
            "--argjson",
            "b",
            "-2",
            "[$a,$b]",
        ],
        None,
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "[1,-2]");
    Ok(())
}

/// `--args`/`--jsonargs` (`num_args = 0..`) consume the *remaining*
/// command line as positional values -- the same clap hyphen-rejection
/// defect as the two-value `--arg`/`--argjson`/etc. flags above, on a
/// different clap shape (found during this issue's own code review, not
/// in the original repro). Verified live against real jq 1.7.1.
#[test]
fn test_args_positional_hyphen_prefixed_values_1150() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-n", "$ARGS.positional", "--args", "-7", "abc"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "[\n  \"-7\",\n  \"abc\"\n]");
    Ok(())
}

#[test]
fn test_jsonargs_positional_hyphen_prefixed_values_1150() -> Result<()> {
    let (stdout, _, code) =
        run_jq_full(&["-n", "$ARGS.positional", "--jsonargs", "-7", "-8"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "[\n  -7,\n  -8\n]");
    Ok(())
}

/// `-L` (`ArgAction::Append`, exactly one value per occurrence -- a
/// different clap shape from every arg above, which is why #1150's
/// `allow_hyphen_values` fix didn't cover it -- and short-only, unlike
/// every other flag in this file: `succinctly jq --help` confirms there is
/// no `--library-path` long form to invoke) had the identical bug: a
/// hyphen-prefixed module directory was rejected by clap's
/// negative-number/unknown-flag heuristic before ever reaching this
/// crate's module-search-path logic. Filed as #1203 during #1150's own
/// review; fixed separately since it needed its own `allow_hyphen_values`
/// site. Verified live against real jq 1.7.1 (`jq -L -mymodules '.'`
/// succeeds there too -- the directory need not exist for a filter that
/// never imports a module).
#[test]
fn test_library_path_hyphen_prefixed_directory_1203() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-L", "-mymodules", "-n", "null"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "null");
    Ok(())
}

/// A string containing a backslash escape sequence, alongside a
/// leading-zero number that triggers normalization -- confirms the escape
/// handling inside `normalize_leading_zero_numbers`'s string-tracking
/// correctly copies the escaped character without misreading it as ending
/// the string early.
#[test]
fn test_argjson_escaped_string_alongside_leading_zero_1094() -> Result<()> {
    let (stdout, _, code) =
        run_jq_full(&["-cn", "--argjson", "n", r#"["a\nb", 007]"#, "$n"], None)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#"["a\nb",7]"#);
    Ok(())
}

/// A leading-zero number combined with scientific notation is accepted
/// (not rejected outright), exercising `normalize_leading_zero_numbers`'s
