#[test]
fn test_slurpfile() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    writeln!(file, r#"{{"x":1}}"#)?;
    writeln!(file, r#"{{"x":2}}"#)?;

    let (output, code) = run_jq_null(
        "$data | length",
        &["--slurpfile", "data", file.path().to_str().unwrap()],
    )?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), "2");
    Ok(())
}

// =============================================================================
// #1093: `--slurpfile`/`--seq` preserve number-literal source fidelity the
// same way `--argjson` does (#1058), instead of round-tripping through
// `serde_json::Value`'s own `f64`/`i64` `Display`. All cases live-verified
// against jq 1.7.1.
// =============================================================================

#[test]
fn test_slurpfile_preserves_number_literal_fidelity_1093() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    writeln!(file, "1.500")?;

    let (stdout, _, code) = run_jq_full(
        &[
            "-cn",
            "--slurpfile",
            "n",
            file.path().to_str().unwrap(),
            "$n",
        ],
        None,
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "[1.500]");
    Ok(())
}

/// Multiple values in one slurped file, one of which needs fidelity
/// preservation -- confirms each value's own byte span is computed
/// correctly, not just the first/only one.
#[test]
fn test_slurpfile_multiple_values_preserve_fidelity_1093() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    writeln!(file, r#"{{"a":1}}"#)?;
    writeln!(file, r#"{{"b":1.500}}"#)?;

    let (stdout, _, code) = run_jq_full(
        &[
            "-cn",
            "--slurpfile",
            "n",
            file.path().to_str().unwrap(),
            "$n",
        ],
        None,
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#"[{"a":1},{"b":1.500}]"#);
    Ok(())
}

/// Values separated by extra whitespace/blank lines -- confirms the
/// leading-whitespace-skip when computing each value's start offset is
/// correct, not just the common single-newline-separated case.
#[test]
fn test_slurpfile_whitespace_between_values_1093() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    writeln!(file, "  {{\"a\":1}}   ")?;
    writeln!(file)?;
    writeln!(file, "  {{\"b\":1.500}}  ")?;

    let (stdout, _, code) = run_jq_full(
        &[
            "-cn",
            "--slurpfile",
            "n",
            file.path().to_str().unwrap(),
            "$n",
        ],
        None,
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), r#"[{"a":1},{"b":1.500}]"#);
    Ok(())
}

/// Genuinely malformed content is still rejected -- fidelity preservation
/// doesn't widen what `--slurpfile` accepts.
#[test]
fn test_slurpfile_malformed_content_still_rejected_1093() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    writeln!(file, "not json")?;

    let (_, _, code) = run_jq_full(
        &[
            "-cn",
            "--slurpfile",
            "n",
            file.path().to_str().unwrap(),
            "$n",
        ],
        None,
    )?;
    assert_ne!(code, 0);
    Ok(())
}

/// `--seq`'s own output format prefixes each value with the same RS
/// (`\x1e`) byte its input uses (RFC 7464), unrelated to this fix -- kept
/// in the expected string, not stripped, to pin the byte-exact output.
#[test]
fn test_seq_preserves_number_literal_fidelity_1093() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["--seq", "-c", "."], Some("\x1e1.500\n"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "\x1e1.500");
    Ok(())
}

/// Multiple RS-separated values, each independently isolated and
/// validated -- confirms fidelity preservation applies per-segment, not
/// just to a single value.
#[test]
fn test_seq_multiple_values_preserve_fidelity_1093() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["--seq", "-c", "."], Some("\x1e1.500\n\x1e2.000\n"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "\x1e1.500\n\x1e2.000");
    Ok(())
}

/// A malformed segment is silently skipped (RFC 7464's own recommendation,
/// unchanged by this fix) while the surrounding valid segments still
/// preserve their fidelity correctly.
#[test]
fn test_seq_malformed_segment_silently_skipped_1093() -> Result<()> {
    let (stdout, _, code) = run_jq_full(
        &["--seq", "-c", "."],
        Some("\x1e1.500\n\x1egarbage\n\x1e2.000\n"),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim_end(), "\x1e1.500\n\x1e2.000");
    Ok(())
}

// =============================================================================
// #1243: `--slurpfile`/`--slurp`/`--seq` tolerate a leading-zero number the
// same way document input and `--argjson` already do (#1094/#1149), instead
// of erroring outright (`--slurpfile`/`--slurp`) or silently dropping the
// record (`--seq`). All cases live-verified against jq 1.7.1.
// =============================================================================

#[test]
fn test_slurpfile_tolerates_leading_zero_number_1243() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    writeln!(file, "007e5")?;

    let (stdout, _, code) = run_jq_full(
        &[
            "-cn",
            "--slurpfile",
            "n",
            file.path().to_str().unwrap(),
            "$n",
        ],
        None,
    )?;
    assert_eq!(code, 0, "stdout: {stdout:?}");
    assert_eq!(stdout.trim_end(), "[7E+5]");
    Ok(())
}

/// A leading-zero number document with plain `--slurp` (not `--slurpfile`)
/// hit the same over-strict `serde_json::Deserializer` validation, found
/// while scoping this fix -- the primary document-input path falls onto
/// this function's slower fallback whenever `--slurp` is set (bypassing the
/// fast lazy path), not just for `--slurpfile`'s own argument file.
#[test]
fn test_slurp_flag_tolerates_leading_zero_number_1243() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["-c", "--slurp", "."], Some("007e5"))?;
    assert_eq!(code, 0, "stdout: {stdout:?}");
    assert_eq!(stdout.trim_end(), "[7E+5]");
    Ok(())
}

#[test]
fn test_seq_tolerates_leading_zero_number_1243() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["--seq", "-c", "."], Some("\x1e007e5\n"))?;
    assert_eq!(code, 0, "stdout: {stdout:?}");
    assert_eq!(stdout.trim_end(), "\x1e7E+5");
    Ok(())
}

/// #1267: swapping `--seq`'s per-record validation to the crate's own
/// zero-allocation grammar validator (performance-motivated) also fixed a
/// real correctness divergence discovered while verifying the swap's
/// grammar equivalence against `serde_json`: a magnitude-overflowing float
/// literal (`1e400`) real jq itself accepts on ordinary document input
/// (`1E+400`, live-verified) used to silently drop as an "unparseable"
/// record here instead, because the old `serde_json::Value`-based
/// validator rejects anything that doesn't fit in a finite `f64`. The new
/// validator is a pure grammar check with no such range rejection, so this
/// now materializes correctly, matching real jq.
#[test]
fn test_seq_accepts_magnitude_overflowing_number_1267() -> Result<()> {
    let (stdout, _, code) = run_jq_full(&["--seq", "-c", "."], Some("\x1e1e400\n"))?;
    assert_eq!(code, 0, "stdout: {stdout:?}");
    assert_eq!(stdout.trim_end(), "\x1e1E+400");
    Ok(())
}

/// Control: a genuinely malformed record is still silently dropped after
/// the validator swap -- the new validator isn't accidentally more lenient
/// on syntax, only on numeric magnitude.
#[test]
fn test_seq_still_drops_genuinely_malformed_record_1267() -> Result<()> {
    let (stdout, _, code) =
        run_jq_full(&["--seq", "-c", "."], Some("\x1enot valid json\n\x1e5\n"))?;
    assert_eq!(code, 0, "stdout: {stdout:?}");
    assert_eq!(stdout.trim_end(), "\x1e5");
    Ok(())
}

/// #2012 (code review): `--seq` had the identical lone-low-surrogate gap
/// #2012 fixed for `--argjson`/`--jsonargs`, reached through a different
/// function (`seq_value_is_valid`) that also gates on `serde_json`
/// validation and had no low-surrogate fallback -- a `--seq` record real
/// jq accepts (substituting U+FFFD, the same #2008 leniency) silently
/// vanished instead of being emitted. Confirmed live against the pinned
/// oracle: `printf '\x1e"\udc00"\n\x1e"ok"\n' | jq --seq -c '.'` prints
/// both records, exit 0.
#[test]
fn test_seq_accepts_lone_low_surrogate_2012() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["--seq", "-c", "."], Some("\x1e\"\\udc00\"\n\x1e\"ok\"\n"))?;
    assert_eq!(code, 0, "stderr: {stderr}");
    assert_eq!(
        stdout.trim_end(),
        "\x1e\"\u{FFFD}\"\n\x1e\"ok\"",
        "stdout: {stdout:?}"
    );
    Ok(())
}

/// #2012 (code review): the composed leading-zero + low-surrogate case
/// must be accepted through `--seq` too, matching `--argjson`'s own
/// composed-fix regression guard. Confirmed live against the pinned
/// oracle: `printf '\x1e[007,"\udc00"]\n' | jq --seq -c '.'` =>
/// `[7,"�"]`, exit 0.
#[test]
fn test_seq_composes_leading_zero_and_low_surrogate_fixes_2012() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["--seq", "-c", "."], Some("\x1e[007,\"\\udc00\"]\n"))?;
    assert_eq!(code, 0, "stderr: {stderr}");
    assert_eq!(
        stdout.trim_end(),
        "\x1e[7,\"\u{FFFD}\"]",
        "stdout: {stdout:?}"
    );
    Ok(())
}

/// #2240: `--seq` shares the same leading/trailing-dot leniency
/// `--argjson`/`--jsonargs` gained, through the identical
/// `seq_value_is_valid`/`normalize_json_leniently` path #2012's own tests
/// above already exercise for the other two leniencies. Also composes with
/// a leading zero in the same value (`.05` sharing a record with `007`),
/// mirroring the #2012 composed-fix regression guard just above.
#[test]
fn test_seq_accepts_dot_leniency_2240() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some("\x1e.05\n"))?;
    assert_eq!(code, 0, "stderr: {stderr}");
    assert_eq!(stdout.trim_end(), "\x1e0.05", "stdout: {stdout:?}");

    let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some("\x1e007.e5\n"))?;
    assert_eq!(code, 0, "stderr: {stderr}");
    assert_eq!(stdout.trim_end(), "\x1e7E+5", "stdout: {stdout:?}");
    Ok(())
}

/// A hyphen-prefixed `--slurpfile`/`--rawfile` FILE value must reach this
/// crate's own file-open logic, not get rejected by clap as an unknown
/// flag first (#1150, same `allow_hyphen_values` fix as `--arg`/
/// `--argjson`). Uses a nonexistent filename -- the point is only to
/// distinguish clap's "unexpected argument" rejection (the pre-fix
/// failure mode) from this crate's own "no such file" error (proof the
/// value was accepted and passed through), not to exercise real file I/O.
#[test]
fn test_slurpfile_rawfile_hyphen_prefixed_filename_reaches_file_open_1150() -> Result<()> {
    let (_, stderr, code) =
        run_jq_full(&["-n", "--slurpfile", "n", "-nonexistent.json", "$n"], None)?;
    assert_ne!(code, 0);
    assert!(
        !stderr.contains("unexpected argument"),
        "clap should not reject the hyphen-prefixed value: {stderr}"
    );

    let (_, stderr, code) = run_jq_full(&["-n", "--rawfile", "n", "-nonexistent.txt", "$n"], None)?;
    assert_ne!(code, 0);
    assert!(
        !stderr.contains("unexpected argument"),
        "clap should not reject the hyphen-prefixed value: {stderr}"
    );
    Ok(())
}

#[test]
fn test_rawfile() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    write!(file, "Hello, World!")?;

    let (output, code) = run_jq_null(
        "$content",
        &["--rawfile", "content", file.path().to_str().unwrap(), "-r"],
    )?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), "Hello, World!");
    Ok(())
}

// =============================================================================
// Filter File Tests
// =============================================================================

#[test]
fn test_from_file() -> Result<()> {
    let mut filter_file = NamedTempFile::new()?;
    writeln!(filter_file, ".name")?;

    let mut input_file = NamedTempFile::new()?;
    writeln!(input_file, r#"{{"name":"Alice"}}"#)?;

    let (output, _code) = spawn_with_signal_retry(
        || {
            let mut cmd = Command::new(succinctly_bin());
            cmd.arg("jq")
                .arg("-f")
                .arg(filter_file.path())
                .arg(input_file.path());
            cmd
        },
        None,
    )?;

    let stdout = String::from_utf8(output.stdout)?;
    assert_eq!(stdout.trim(), r#""Alice""#);
    Ok(())
}

// #2688: `$__loc__` names the *program text* as `"<top-level>"` for a
// filter that isn't sourced from a module -- across the inline form, `-f`
// file form, and nested inside another filter (`map(...)`) -- each row
// cross-checked live against jq 1.7.1.
#[test]
fn test_loc_top_level_2688() -> Result<()> {
    let (stdout, code) = run_jq_null("$__loc__", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"file":"<top-level>","line":1}"#);

    let (stdout, code) = run_jq_stdin("map($__loc__)", "[1,2]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(
        stdout.trim(),
        r#"[{"file":"<top-level>","line":1},{"file":"<top-level>","line":1}]"#
    );

    let mut filter_file = NamedTempFile::new()?;
    writeln!(filter_file, "$__loc__")?;
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "-f", filter_file.path().to_str().unwrap()],
        Some("null"),
    )?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(stdout.trim(), r#"{"file":"<top-level>","line":1}"#);

    Ok(())
}

/// #3029: `$__loc__` is a distinct pseudo-variable token in jq's own lexer,
/// not `'$' IDENT`, so it cannot be used as a *binding* name at any binding
/// site -- `def` `$`-params, `as`, `reduce`/`foreach`, array/object
/// destructuring, and `?//` alternatives are all syntax errors (exit 3) in
/// jq 1.7.1. succinctly used to accept every one of them (ignoring the
/// binding and still answering `$__loc__` with the location). The message
/// wording now matches jq's (the `(Unix shell quoting issues?)` suffix and
/// the column padding remain part of the generic syntax-error divergence
/// recorded in `docs/compliance/jq/limitations.md`); the `expecting` list
/// differs per production exactly as jq's bison states report it, and the
/// `{$name}` shorthand forms have none at all. Every row below was
/// cross-checked live against `/usr/bin/jq` 1.7.1.
#[test]
fn test_loc_is_not_a_binding_name_3029() -> Result<()> {
    for (filter, expecting) in [
        (
            "def h($__loc__): 1; h(1)",
            "syntax error, unexpected $__loc__, expecting IDENT or BINDING",
        ),
        (
            "1 as $__loc__ | $__loc__",
            "syntax error, unexpected $__loc__, expecting BINDING or '[' or '{'",
        ),
        (
            "reduce 1 as $__loc__ (0; .)",
            "syntax error, unexpected $__loc__, expecting BINDING or '[' or '{'",
        ),
        (
            "foreach 1 as $__loc__ (0; .)",
            "syntax error, unexpected $__loc__, expecting BINDING or '[' or '{'",
        ),
        (
            "[1] as [$__loc__] | 2",
            "syntax error, unexpected $__loc__, expecting BINDING or '[' or '{'",
        ),
        (
            r#"{"a":1} as {"a": $__loc__} | 2"#,
            "syntax error, unexpected $__loc__, expecting BINDING or '[' or '{'",
        ),
        (
            "1 as $x ?// $__loc__ | 2",
            "syntax error, unexpected $__loc__, expecting BINDING or '[' or '{'",
        ),
    ] {
        let (_, stderr, code) = run_jq_full(&["-n", filter], None)?;
        assert_eq!(code, 3, "{filter:?}: stderr: {stderr:?}");
        assert!(
            stderr.contains(&format!("jq: error: {expecting} at <top-level>, line 1:\n")),
            "{filter:?}: stderr: {stderr:?}"
        );
        assert!(
            stderr.contains("jq: 1 compile error"),
            "{filter:?}: stderr: {stderr:?}"
        );
    }

    // The `{$name}`/`{$name: Pattern}` shorthand reports a bare
    // `unexpected $__loc__` with no expecting list.
    for filter in [
        r#"{"a":1} as {$__loc__} | 2"#,
        r#"{"a":1} as {$__loc__: .x} | 2"#,
    ] {
        let (_, stderr, code) = run_jq_full(&["-n", filter], None)?;
        assert_eq!(code, 3, "{filter:?}: stderr: {stderr:?}");
        assert!(
            stderr
                .contains("jq: error: syntax error, unexpected $__loc__ at <top-level>, line 1:\n"),
            "{filter:?}: stderr: {stderr:?}"
        );
        assert!(
            stderr.contains("jq: 1 compile error"),
            "{filter:?}: stderr: {stderr:?}"
        );
    }

    // A *bare* `__loc__` parameter stays an ordinary identifier (`def
    // h(__loc__): 1; h(1)` answers `1` in both jq and succinctly).
    let (stdout, code) = run_jq_null("def h(__loc__): 1; h(1)", &[])?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "1");
    Ok(())
}

/// #3029: `$ENV` is an ordinary, shadowable binding in jq -- an inner
/// `as $ENV` / `def f($ENV)` wins lexically over the environment. succinctly
/// used to answer the environment object for every `$ENV` reference because
/// `dollar_var_expr` lowers them all to `Expr::Env` at parse time; the
/// lexical rewrite now lives in resolve's scope walk. Every row below was
/// cross-checked live against `/usr/bin/jq` 1.7.1.
#[test]
fn test_bound_env_shadows_the_environment_3029() -> Result<()> {
    for (filter, expected) in [
        ("1 as $ENV | $ENV", "1"),
        ("def h($ENV): $ENV; h(1)", "1"),
        ("1 as $ENV | 1 as $ENV | $ENV", "1"),
        ("reduce 1 as $ENV (2; $ENV)", "1"),
        ("foreach 1 as $ENV (2; $ENV) | .", "1"),
        (r#"{"a":1} as {"a": $ENV} | $ENV"#, "1"),
        ("[1] as [$ENV] | $ENV", "1"),
    ] {
        let (stdout, code) = run_jq_null(filter, &["-c"])?;
        assert_eq!(code, 0, "{filter:?}: stdout: {stdout:?}");
        assert_eq!(stdout.trim(), expected, "{filter:?}");
    }

    // Indexing a bound (non-environment) `$ENV` fails like any other bound
    // number, not by silently going through the environment table.
    let (_, stderr, code) = run_jq_full(&["-nc", "1 as $ENV | $ENV.x"], None)?;
    assert_eq!(code, 5, "stderr: {stderr:?}");
    assert!(
        stderr.contains("Cannot index number with string \"x\""),
        "stderr: {stderr:?}"
    );

    // Lexical scope: a `def`'s body keeps the environment at its own textual
    // position; the lazy `1 as $ENV | f` call cannot see the later binding.
    let (env_out, _) = run_jq_null("$ENV", &["-c"])?;
    let (def_env_out, code) = run_jq_null("def f: $ENV; 1 as $ENV | f", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(
        def_env_out.trim(),
        env_out.trim(),
        "the def-body `$ENV` must still answer the environment object"
    );
    Ok(())
}
/// that module's own canonical (symlink-resolved) file path, not
/// `"<top-level>"`. Line stays module-relative -- already correct before
/// this fix, since each module is parsed on its own -- so a multi-line def
/// pins that only `file` was wrong, not `line`.
///
/// Expected `file` is computed via `std::fs::canonicalize`, not a literal:
/// the test's own temp directory differs every run, and on macOS `/tmp` is
/// itself a symlink to `/private/tmp` -- exactly the realpath case jq
/// applies, so comparing against the raw `tempdir()` path would spuriously
/// fail there.
#[test]
fn test_loc_include_names_the_modules_own_canonical_file_2774() -> Result<()> {
    let lib_dir = tempfile::tempdir()?;
    let module_path = lib_dir.path().join("loc_module.jq");
    std::fs::write(&module_path, "def f: $__loc__;\ndef g:\n  $__loc__;\n")?;
    let canonical = std::fs::canonicalize(&module_path)?;
    let canonical_str = canonical.to_string_lossy();

    for (call, line) in [("f", 1), ("g", 3)] {
        let (output, code) = spawn_with_signal_retry(
            || {
                let mut command = Command::new(succinctly_bin());
                command
                    .args(["jq", "-L"])
                    .arg(lib_dir.path())
                    .args(["-nc", &format!(r#"include "loc_module"; {call}"#)]);
                command
            },
            None,
        )?;
        let stdout = String::from_utf8(output.stdout)?;
        let stderr = String::from_utf8(output.stderr)?;
        assert_eq!(code, 0, "{call}: stderr: {stderr:?}");
        assert_eq!(
            stdout.trim_end(),
            format!(r#"{{"file":"{canonical_str}","line":{line}}}"#),
            "{call}"
        );
    }
    Ok(())
}

/// #2774 control: the *main filter's* own `$__loc__` still reports
/// `"<top-level>"` even while a module is loaded alongside it -- the fix
/// only stamps a module-sourced def's own body, never the filter that
/// `include`s it.
#[test]
fn test_loc_main_filter_stays_top_level_alongside_an_include_2774() -> Result<()> {
    let lib_dir = tempfile::tempdir()?;
    std::fs::write(lib_dir.path().join("mod.jq"), "def f: 1;\n")?;
    let (output, code) = spawn_with_signal_retry(
        || {
            let mut command = Command::new(succinctly_bin());
            command
                .args(["jq", "-L"])
                .arg(lib_dir.path())
                .args(["-nc", r#"include "mod"; $__loc__"#]);
            command
        },
        None,
    )?;
    let stdout = String::from_utf8(output.stdout)?;
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(stdout.trim_end(), r#"{"file":"<top-level>","line":1}"#);
    Ok(())
}

/// #2774: `import "m" as m; m::f` -- a namespaced call into an imported
/// module -- reports the module's own file too, the same as `include`.
#[test]
fn test_loc_import_names_the_modules_own_canonical_file_2774() -> Result<()> {
    let lib_dir = tempfile::tempdir()?;
    let module_path = lib_dir.path().join("loc_module.jq");
    std::fs::write(&module_path, "def f: $__loc__;\n")?;
    let canonical = std::fs::canonicalize(&module_path)?;
    let canonical_str = canonical.to_string_lossy();

    let (output, code) = spawn_with_signal_retry(
        || {
            let mut command = Command::new(succinctly_bin());
            command
                .args(["jq", "-L"])
                .arg(lib_dir.path())
                .args(["-nc", r#"import "loc_module" as m; m::f"#]);
            command
        },
        None,
    )?;
    let stdout = String::from_utf8(output.stdout)?;
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(
        stdout.trim_end(),
        format!(r#"{{"file":"{canonical_str}","line":1}}"#)
    );
    Ok(())
}

/// #2774: `~/.jq` gets the same treatment as an `include`d module -- its
/// own defs' `$__loc__` names `~/.jq`'s own canonical path, not
/// `"<top-level>"`.
#[test]
fn test_loc_home_jq_names_home_jqs_own_canonical_file_2774() -> Result<()> {
    let temp_home = tempfile::tempdir()?;
    let jq_path = temp_home.path().join(".jq");
    std::fs::write(&jq_path, "def g:\n  $__loc__;\n")?;
    let canonical = std::fs::canonicalize(&jq_path)?;
    let canonical_str = canonical.to_string_lossy();

    let (output, code) = spawn_jq_with_env(&["-nc", "g"], "HOME", temp_home.path(), None)?;
    let stdout = String::from_utf8(output.stdout)?;
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(
        stdout.trim_end(),
        format!(r#"{{"file":"{canonical_str}","line":2}}"#)
    );
    Ok(())
}

/// #2774: a module reached through a symlink reports the symlink's
/// *target* path (jq's own realpath behavior), not the symlink path it was
/// `-L`'d through.
#[test]
#[cfg(unix)]
fn test_loc_symlinked_module_names_the_canonical_target_2774() -> Result<()> {
    let real_dir = tempfile::tempdir()?;
    let real_path = real_dir.path().join("real.jq");
    std::fs::write(&real_path, "def real_target_fn: $__loc__;\n")?;
    let canonical = std::fs::canonicalize(&real_path)?;
    let canonical_str = canonical.to_string_lossy();

    let symlink_dir = tempfile::tempdir()?;
    std::os::unix::fs::symlink(&real_path, symlink_dir.path().join("real.jq"))?;

    let (output, code) = spawn_with_signal_retry(
        || {
            let mut command = Command::new(succinctly_bin());
            command
                .args(["jq", "-L"])
                .arg(symlink_dir.path())
                .args(["-nc", r#"include "real"; real_target_fn"#]);
            command
        },
        None,
    )?;
    let stdout = String::from_utf8(output.stdout)?;
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(
        stdout.trim_end(),
        format!(r#"{{"file":"{canonical_str}","line":1}}"#)
    );
    Ok(())
}

