/// #478 item 3: `jq --preserve-input '.'` in pretty mode (no `-c`) used to
/// collapse duplicate object keys via `standard_json_to_jq_value`'s
/// `IndexMap`, unlike its own `-c` output. Fixed incidentally by #532's
/// `Expr::Identity => GenericResult::OneCursor` change, which routes
/// identity through the cursor-based `print_json` path in both modes —
/// pinned here as a regression guard rather than a code change.
#[test]
fn test_preserve_input_pretty_preserves_duplicate_keys() -> Result<()> {
    let input = r#"{"a":1,"a":2}"#;

    let (compact, code) = run_jq_stdin(".", input, &["-c", "--preserve-input"])?;
    assert_eq!(code, 0);
    assert_eq!(compact.trim(), r#"{"a":1,"a":2}"#);

    let (pretty, code) = run_jq_stdin(".", input, &["--preserve-input"])?;
    assert_eq!(code, 0);
    assert_eq!(pretty, "{\n  \"a\": 1,\n  \"a\": 2\n}\n");

    Ok(())
}

/// #607: `first(.[])`/`last(.[])` (the `Expr::FirstExpr`/`LastExpr` one-arg
/// stream form `first(f)`/`last(f)` compiles to — distinct from the bare
/// zero-arg `first`/`last` keyword, which is `Builtin::First`/`Last`) had no
/// native arm in `eval_generic::eval_single`, so it fell through the
/// catch-all `to_owned()` bridge and collapsed duplicate keys inside the
/// selected element before the extraction even ran — unlike `.[0]`, which
/// #532 already routed through the cursor-preserving path.
#[test]
fn test_preserve_input_first_last_expr_preserve_duplicate_keys() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3,"b":4}]"#;

    let (first_compact, _, code) =
        run_jq_full(&["-c", "--preserve-input", "first(.[])"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(first_compact.trim(), r#"{"a":1,"a":2}"#);

    let (first_pretty, _, code) = run_jq_full(&["--preserve-input", "first(.[])"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(first_pretty, "{\n  \"a\": 1,\n  \"a\": 2\n}\n");

    let (last_compact, _, code) =
        run_jq_full(&["-c", "--preserve-input", "last(.[])"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(last_compact.trim(), r#"{"b":3,"b":4}"#);

    let (last_pretty, _, code) = run_jq_full(&["--preserve-input", "last(.[])"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(last_pretty, "{\n  \"b\": 3,\n  \"b\": 4\n}\n");

    Ok(())
}

/// #607: the bare zero-arg `first`/`last` keyword (`Builtin::First`/`Last`,
/// equivalent to `.[0]`/`.[-1]`) called `elements.get(...)` instead of the
/// `get_cursor(...)` sibling `.[0]`/`.[-1]` (`Expr::Index`) already used.
#[test]
fn test_preserve_input_bare_first_last_preserve_duplicate_keys() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3,"b":4}]"#;

    let (first, _, code) = run_jq_full(&["-c", "--preserve-input", "first"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(first.trim(), r#"{"a":1,"a":2}"#);

    let (last, _, code) = run_jq_full(&["-c", "--preserve-input", "last"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(last.trim(), r#"{"b":3,"b":4}"#);

    Ok(())
}

/// #607: computed-key indexing (`.[$k]`/`.[(expr)]`, `Expr::IndexExpr`) went
/// through `index_one_generic`'s old `fields.find`/`elements.get` calls —
/// the same bug class as `first`/`last` above but reached via a different
/// code path (`eval_index_expr`). `.[(1-1)]` forces a genuinely computed
/// index rather than one the parser folds into a literal `Expr::Index`.
#[test]
fn test_preserve_input_computed_index_preserves_duplicate_keys() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3,"b":4}]"#;

    let (compact, _, code) = run_jq_full(&["-c", "--preserve-input", ".[(1-1)]"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(compact.trim(), r#"{"a":1,"a":2}"#);

    Ok(())
}

/// #1385: in jq mode a repeated object key collapses to its *first*
/// position holding its *last* value. Every filter here was captured from
/// the pin (`/usr/bin/jq`, jq-1.7.1) on `{"b":1,"a":2,"b":3}`; the golden
/// corpus carries the same cases, this pins them at the CLI boundary where
/// `--preserve-input`'s exemption below can sit beside them.
#[test]
fn test_duplicate_keys_collapse_last_wins_1385() -> Result<()> {
    let input = r#"{"b":1,"a":2,"b":3}"#;
    for (filter, expected) in [
        (".", r#"{"b":3,"a":2}"#),
        ("length", "2"),
        ("keys", r#"["a","b"]"#),
        ("keys_unsorted", r#"["b","a"]"#),
        ("[.[]]", "[3,2]"),
        ("[paths]", r#"[["b"],["a"]]"#),
        ("to_entries|length", "2"),
        // #2626 control. In yq mode the same three answered `2` from a
        // *collapsed copy* of the document while bare `length` answered 3,
        // and giving `Expr::Arithmetic`/`Expr::Negate` native arms moved
        // them to 3. Here `2` is the right answer and must not move with
        // them: jq really does build an object with one `b`, so
        // `COLLAPSE_DUPLICATE_KEYS` makes the streaming route agree with the
        // collapsed one. Captured from /usr/bin/jq 1.7.1.
        ("length + 0", "2"),
        ("(keys|length) + 0", "2"),
        ("(-length)", "-2"),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }
    Ok(())
}

/// #1385: the collapse is the printer's, not one filter's, so every
/// cursor-preserving navigation reaches it — `.[0]`, `first`/`last` and a
/// computed index all previously emitted both occurrences.
#[test]
fn test_duplicate_keys_collapse_through_navigation_1385() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3,"b":4}]"#;
    for (filter, expected) in [
        (".[]", "{\"a\":2}\n{\"b\":4}"),
        (".[0]", r#"{"a":2}"#),
        ("first(.[])", r#"{"a":2}"#),
        ("last(.[])", r#"{"b":4}"#),
        ("first", r#"{"a":2}"#),
        ("last", r#"{"b":4}"#),
        (".[(1-1)]", r#"{"a":2}"#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }
    Ok(())
}

/// #1385: nesting and pretty-printing go through the same `print_json` arm,
/// and a key repeated with a *different escape spelling* is still the same
/// key — `"a\/b"` and `"a/b"` both decode to `a/b`, which the raw-span fast
/// path cannot see, so it falls back to comparing decoded keys.
#[test]
fn test_duplicate_keys_collapse_nested_and_escaped_1385() -> Result<()> {
    let (out, _, code) = run_jq_full(
        &["-c", "."],
        Some(r#"{"x":{"b":1,"a":2,"b":3},"y":[{"a":1,"a":2}]}"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), r#"{"x":{"b":3,"a":2},"y":[{"a":2}]}"#);

    let (pretty, _, code) = run_jq_full(&["."], Some(r#"{"a":1,"a":2}"#))?;
    assert_eq!(code, 0);
    assert_eq!(pretty, "{\n  \"a\": 2\n}\n");

    let (escaped, _, code) = run_jq_full(&["-c", "."], Some(r#"{"a\/b":1,"a/b":2}"#))?;
    assert_eq!(code, 0);
    assert_eq!(escaped.trim(), r#"{"a/b":2}"#);

    Ok(())
}

/// #1385: the duplicate scan keys off a fixed-size stack buffer and spills
/// to a heap `Vec` past it, so an object wider than that buffer exercises a
/// different comparison path. 40 fields with the duplicate at the tail puts
/// both the spill and the sorted compare in play.
#[test]
fn test_duplicate_keys_collapse_wide_object_1385() -> Result<()> {
    let mut input = String::from("{");
    for i in 0..40 {
        input.push_str(&format!("\"k{i}\":{i},"));
    }
    input.push_str("\"k0\":999}");

    let (out, _, code) = run_jq_full(&["-c", "length"], Some(&input))?;
    assert_eq!(code, 0);
    assert_eq!(
        out.trim(),
        "40",
        "the repeated k0 must not be counted twice"
    );

    let (first, _, code) = run_jq_full(&["-c", ".k0"], Some(&input))?;
    assert_eq!(code, 0);
    assert_eq!(first.trim(), "999", "last occurrence wins");

    // `.` is what drives the *printer*'s span scan, which has its own
    // pairwise-vs-sorted split; `length` and `.k0` never reach it. Without
    // this the sorted branch went untested.
    let (printed, _, code) = run_jq_full(&["-c", "."], Some(&input))?;
    assert_eq!(code, 0);
    let expected: String = core::iter::once(String::from("{\"k0\":999"))
        .chain((1..40).map(|i| format!(",\"k{i}\":{i}")))
        .chain(core::iter::once(String::from("}")))
        .collect();
    assert_eq!(
        printed.trim(),
        expected,
        "k0 keeps its first position and its last value"
    );

    Ok(())
}

/// #1588: an object wide enough to saturate `KeyHashes`'s 786,432-key
/// ceiling hands itself to `object_keys_repeat` -- a whole-object batch
/// probe -- instead of letting the streaming table double again. This pins
/// that the handoff preserves jq's collapse rule; the semantics themselves
/// are covered cheaply by `object_keys_repeat_tests` in `src/jq/document.rs`.
///
/// **The duplicate sits past the ceiling on purpose.** That is the case a
/// wrong fix silently gets wrong: a table that merely *stopped inserting*
/// when full would stream every key after saturation unchecked, report
/// 400,000 keys where jq reports 399,999, and pass every test built from a
/// duplicate near the head. The batch probe covers the whole object,
/// including the fields the streaming walk has not reached, which is what
/// makes retiring the probe on a clean answer sound.
///
/// **Every filter here iterates the key array**, which is what it takes to
/// reach `DistinctKeyCursors` at all. The obvious spellings do not: bare
/// `keys_unsorted | length`, `.k0000005` and `keys_unsorted | index(...)`
/// are all answered by `census`, the batch walk, and keep reporting jq's
/// numbers with the streaming probe disabled entirely -- verified by
/// building the arm out and watching those three stay green while the two
/// below flipped to 400000 and 2.
///
/// Every expectation below is jq 1.7.1's own output on the same input.
#[test]
fn test_duplicate_keys_collapse_past_the_probe_ceiling_1588() -> Result<()> {
    // 800,000 fields: past `KeyHashes::MAX_SLOTS`'s 786,432-key saturation
    // point, and no further -- this test's runtime is linear in it, so the
    // margin is deliberately thin and moves with the ceiling. Fed on stdin,
    // never argv (Linux CI's `ARG_MAX`).
    const FIELDS: usize = 800_000;
    const DUPLICATE_AT: usize = 799_000;
    // Where the ceiling bites, and so where the collapsed list has to
    // resume: `KeyHashes::MAX_SLOTS` * 3/4.
    const SATURATES_AT: usize = 786_432;

    // `repeat_at` places the object's *only* duplicate: `None` for a clean
    // document, otherwise the field index whose key repeats `k0000005`.
    let build = |repeat_at: Option<usize>| {
        let mut out = String::from("{");
        for i in 0..FIELDS {
            if i > 0 {
                out.push(',');
            }
            if repeat_at == Some(i) {
                out.push_str("\"k0000005\":999999");
            } else {
                out.push_str(&format!("\"k{i:07}\":{i}"));
            }
        }
        out.push('}');
        out
    };

    // One invocation per document, because each already collects the whole
    // key array: `length` proves the collapse rule, the three keys either
    // side of the saturation point prove the collapsed list resumes exactly
    // where the streaming walk stopped (an off-by-one in that resume shows
    // here and nowhere else, since every other key is identical either way),
    // and the final count proves the survivor survives exactly once.
    let probe = format!(
        "[keys_unsorted[]] | [length, .[{}], .[{}], .[{}], \
         ([.[] | select(. == \"k0000005\")] | length)]",
        SATURATES_AT - 1,
        SATURATES_AT,
        SATURATES_AT + 1,
    );

    // Clean: the probe proves the whole object distinct at saturation and
    // retires, and every remaining key still streams.
    let (clean, _, code) = run_jq_full(&["-c", &probe], Some(&build(None)))?;
    assert_eq!(code, 0);
    assert_eq!(
        clean.trim(),
        r#"[800000,"k0786431","k0786432","k0786433",1]"#,
        "retiring a clean probe must not drop or repeat a key after it"
    );

    let (repeated, _, code) = run_jq_full(&["-c", &probe], Some(&build(Some(DUPLICATE_AT))))?;
    assert_eq!(code, 0);
    assert_eq!(
        repeated.trim(),
        r#"[799999,"k0786431","k0786432","k0786433",1]"#,
        "a duplicate past the ceiling still collapses, once, in place"
    );

    // The key *at* the saturation boundary is the seam's own edge case: the
    // settle seeds itself from the table, which holds every key before this
    // one, and walks everything after it -- so this single key belongs to
    // neither and is added by hand. A document whose only duplicate involves
    // it is the one shape that notices if that hand-off is dropped; with the
    // duplicate anywhere else, the exact re-walk finds it anyway and reports
    // the right answer for the wrong reason.
    let (boundary, _, code) = run_jq_full(
        &["-c", "[keys_unsorted[]] | length"],
        Some(&build(Some(SATURATES_AT))),
    )?;
    assert_eq!(code, 0);
    assert_eq!(
        boundary.trim(),
        "799999",
        "the key being probed when the ceiling is reached must reach the seed"
    );

    Ok(())
}

/// #1385 review: collapsing must be linear in the field count. Picking each
/// surviving key by scanning the keys accepted so far made a single
/// duplicate in a 100K-field object take 8.5 s where not collapsing at all
/// took 0.02 s -- a quadratic blowup on exactly the input shape this crate
/// exists to handle well.
///
/// 20K fields is small enough to stay a unit test and large enough that the
/// quadratic form would not finish in any reasonable time (it is 400M key
/// comparisons; the linear form is 20K hash lookups).
#[test]
fn test_duplicate_keys_collapse_is_linear_1385() -> Result<()> {
    const FIELDS: usize = 20_000;
    let mut input = String::from("{");
    for i in 0..FIELDS {
        input.push_str(&format!("\"k{i}\":{i},"));
    }
    input.push_str("\"k0\":999}");

    let (out, _, code) = run_jq_full(&["-c", "length"], Some(&input))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), FIELDS.to_string());

    let (printed, _, code) = run_jq_full(&["-c", "."], Some(&input))?;
    assert_eq!(code, 0);
    assert!(
        printed.starts_with("{\"k0\":999,\"k1\":1,"),
        "got {printed:.40}"
    );
    assert!(printed
        .trim()
        .ends_with(&format!("\"k{}\":{}}}", FIELDS - 1, FIELDS - 1)));

    Ok(())
}

/// #1385 review: a key that will not decode has no name to collapse *on*,
/// so it takes part in no collapse and is echoed from its raw source span.
/// Skipping it instead deleted the field from output -- `{"a\q":1,"b":2}`
/// printed as `{"b":2}` -- while `length`, `keys` and `[.[]]` went on
/// counting it, which is the very incoherence #1385 set out to remove.
///
/// Real jq rejects all of these at parse time (`Invalid escape`, `Invalid
/// \uXXXX\uXXXX surrogate pair escape`); succinctly semi-indexes rather
/// than validates, so they reach the evaluator and must at least be
/// self-consistent. See `docs/compliance/jq/limitations.md`.
#[test]
fn test_undecodable_keys_are_not_duplicates_1385() -> Result<()> {
    for (input, printed, length, values) in [
        (r#"{"a\q":1,"b":2}"#, r#"{"a\q":1,"b":2}"#, "2", "[1,2]"),
        (
            r#"{"\ud800":1,"\ud800":2}"#,
            r#"{"\ud800":1,"\ud800":2}"#,
            "2",
            "[1,2]",
        ),
        // A genuine duplicate alongside one: `b` collapses, the
        // undecodable key stays exactly where it was.
        (
            r#"{"a\q":1,"b":2,"b":3}"#,
            r#"{"a\q":1,"b":3}"#,
            "2",
            "[1,3]",
        ),
    ] {
        let (out, _, code) = run_jq_full(&["-c", "."], Some(input))?;
        assert_eq!(code, 0, "input {input}");
        assert_eq!(out.trim(), printed, "input {input}");

        let (len, _, code) = run_jq_full(&["-c", "length"], Some(input))?;
        assert_eq!(code, 0, "input {input}");
        assert_eq!(len.trim(), length, "input {input}");

        let (vals, _, code) = run_jq_full(&["-c", "[.[]]"], Some(input))?;
        assert_eq!(code, 0, "input {input}");
        assert_eq!(vals.trim(), values, "input {input}");
    }
    Ok(())
}

/// #1642: `length`, `keys`, `keys_unsorted`, `to_entries` and `has` must all
/// agree on whether a document with an undecodable object key is usable --
/// before this fix, `keys`/`to_entries`/`has` raised (exit 5) on exactly the
/// same document `.`/`length`/bare `keys_unsorted` accepted (exit 0), so a
/// script's behaviour depended on which builtin it happened to call. This
/// extends `test_undecodable_keys_are_not_duplicates_1385`'s guarantee (a
/// key that will not decode is never a duplicate) to the two builtins that
/// used to raise before ever reaching it.
///
/// `keys`/`to_entries` report the bad key re-escaped from a real
/// materialized `String` (`a\q`'s single source backslash doubles to
/// `\\`), where bare `keys_unsorted` echoes the exact source bytes verbatim
/// -- an inherent, harmless difference between a genuinely-lazy raw-byte
/// echo and a value that has actually been materialized, not a new
/// inconsistency.
#[test]
fn test_undecodable_key_builtins_agree_1642() -> Result<()> {
    let doc = r#"{"a\q":1,"b":2}"#;

    let (out, _, code) = run_jq_full(&["-c", "length"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "2");

    let (out, _, code) = run_jq_full(&["-c", "keys_unsorted"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), r#"["a\q","b"]"#);

    let (out, _, code) = run_jq_full(&["-c", "keys"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "[\"a\\\\q\",\"b\"]");

    let (out, _, code) = run_jq_full(&["-c", "to_entries"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(
        out.trim(),
        "[{\"key\":\"a\\\\q\",\"value\":1},{\"key\":\"b\",\"value\":2}]"
    );

    let (out, _, code) = run_jq_full(&["-c", r#"has("b")"#], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "true");

    // #1739 review: `has()`'s new native arm (`DocumentFields::contains`,
    // `src/jq/document.rs`) must also match the decode-failure key's own
    // #1642 fallback spelling, not just an ordinary sibling key -- the
    // pre-#1739 `JsonFields::contains` this replaced never did (it skipped
    // any undecodable key outright, matching neither `keys`'s established
    // fallback-preservation contract nor `has()`'s own eventual fix here).
    // Queried indirectly via `keys[0]`, not a hand-escaped literal, so this
    // stays correct regardless of exactly how the fallback re-escapes.
    let (out, _, code) = run_jq_full(&["-c", "keys[0] as $k | has($k)"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "true");

    // Two decode-failure keys, byte-identical source: #1385 already pins
    // that they never collapse under `.`/`length`/`[.[]]`; extend that to
    // `keys`/`to_entries`, which used to raise before ever getting the
    // chance to (dis)agree.
    let dup_doc = r#"{"\ud800":1,"\ud800":2}"#;

    let (out, _, code) = run_jq_full(&["-c", "length"], Some(dup_doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "2");

    let (out, _, code) = run_jq_full(&["-c", "keys_unsorted"], Some(dup_doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), r#"["\ud800","\ud800"]"#);

    let (out, _, code) = run_jq_full(&["-c", "keys"], Some(dup_doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "[\"\\\\ud800\",\"\\\\ud800\"]");

    let (out, _, code) = run_jq_full(&["-c", "to_entries"], Some(dup_doc))?;
    assert_eq!(code, 0);
    assert_eq!(
        out.trim(),
        "[{\"key\":\"\\\\ud800\",\"value\":1},{\"key\":\"\\\\ud800\",\"value\":2}]"
    );

    Ok(())
}

/// #1642 follow-up: `paths`/`leaf_paths` were left on the old
/// `field.key_str()` (`None` for a decode-failure key, same as for a
/// #1194 key the grammar never allowed), so they silently dropped a
/// decode-failure key's path while `keys`/`length`/`to_entries` -- routed
/// through the shared `key_display_string` -- correctly reported it. Same
/// "one document, many answers" failure `test_undecodable_key_builtins_agree_1642`
/// pins for the other five builtins, just on this pair.
#[test]
fn test_paths_and_leaf_paths_agree_with_keys_on_decode_failure_1642() -> Result<()> {
    let doc = r#"{"a\q":1,"b":2}"#;

    let (out, _, code) = run_jq_full(&["-c", "keys"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "[\"a\\\\q\",\"b\"]");

    let (out, _, code) = run_jq_full(&["-c", "paths"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "[\"a\\\\q\"]\n[\"b\"]");

    let (out, _, code) = run_jq_full(&["-c", "leaf_paths"], Some(doc))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "[\"a\\\\q\"]\n[\"b\"]");

    Ok(())
}

/// #1829: `paths`/`leaf_paths` dispatch, via the shipped CLI, straight to
/// `eval_generic.rs`'s own native `Builtin::Paths`/`Builtin::LeafPaths` arm
/// (`collect_paths_generic`) -- a *different* code path from the one
/// `test_paths_and_leaf_paths_agree_with_keys_on_decode_failure_1642` above
/// exercises for a merely-undecodable key. A structurally malformed key
/// (#1194, the grammar never allowed it at all -- e.g. a trailing unpaired
/// member) used to be silently skipped there instead of raising, so `paths`/
/// `leaf_paths` disagreed with `keys` on the very shape #1194 exists to
/// catch, and did so specifically at the CLI: this exact regression was
/// invisible to a unit test that calls `succinctly::jq::eval` directly,
/// since that library entry point routes through a completely different,
/// separately-implemented `eval.rs` copy that never had this gap in the
/// same way. Confirmed via `git bisect`-style manual check: unmodified
/// `main`'s CLI binary returns `["a"]` (exit 0, `b`'s path silently
/// dropped) for the first two queries below; this fix makes them agree
/// with `keys`.
#[test]
fn test_paths_and_leaf_paths_raise_on_structurally_malformed_key_1829() -> Result<()> {
    let doc = r#"{"a":1,"b"}"#;

    let (_, _, code) = run_jq_full(&["-c", "paths"], Some(doc))?;
    assert_ne!(code, 0, "paths must raise, not silently drop b's path");

    let (_, _, code) = run_jq_full(&["-c", "leaf_paths"], Some(doc))?;
    assert_ne!(code, 0, "leaf_paths must raise, not silently drop b's path");

    let (_, _, code) = run_jq_full(&["-c", "keys"], Some(doc))?;
    assert_ne!(code, 0, "sanity: keys already raises on this document");

    Ok(())
}

/// #1642 follow-up: `to_owned`/`materialize` (`-S`, `-s`) build an
/// `IndexMap<String, _>` keyed by `key_display_string`'s fallback. Two
/// *different* decode-failure keys can share that fallback spelling
/// (byte-identical raw escapes, or two separate bad `\u` escapes that both
/// lossy-decode to U+FFFD), and #1385 forbids treating them as the same key
/// -- but the map cannot hold two entries under one string. Before this fix
/// that silently kept only the last value (worse than #1247's original
/// raise, which turned into quieter data loss instead of louder
/// consistency); now it raises. See `DisplayKeyGuard` in
/// `src/jq/document.rs`.
///
/// `.,.` was a third raising route here until #2103. It no longer is, and
/// the reason is not that the guard weakened: `.,.` forwards the **root
/// cursor** to the printer, twice, and never builds the `IndexMap` the
/// collision is *about*. It only raised because the eager M2 route
/// materialized the ambient value through `to_owned_with_cursor` before
/// evaluating anything, so every filter paid for a map nothing had asked
/// for. With every M2 filter streaming (#2103), `.,.` echoes the raw source
/// bytes exactly as `.` already did -- pinned explicitly below, so the row
/// leaving the raising loop is a recorded expectation rather than a
/// silently dropped assertion. Real jq 1.7.1 rejects this document at parse
/// time (exit 5, `Invalid \uXXXX\uXXXX surrogate pair escape`) for `.`,
/// `.,.` and `-S .` alike; succinctly's divergence on `.` predates #2103 and
/// `.,.` has now joined it. `-S`/`-s` still raise, because rendering both
/// keys into one map is what the collision is.
#[test]
fn test_materializing_route_raises_on_colliding_decode_failure_keys_1642() -> Result<()> {
    let dup_doc = r#"{"\ud800":1,"\ud800":2}"#;

    for args in [&["-Sc", "."][..], &["-c", "-s", "."][..]] {
        let (out, err, code) = run_jq_full(args, Some(dup_doc))?;
        assert_ne!(
            code, 0,
            "args {args:?} should raise rather than silently drop a value, out: {out:?}"
        );
        assert!(err.contains("ambiguous"), "args {args:?}, stderr: {err}");
    }

    // #2103: `.,.` streams the root cursor straight to the printer, so it
    // echoes the document's own bytes twice at exit 0 -- no map, no
    // collision, nothing to raise about.
    let (out, err, code) = run_jq_full(&["-c", ".,."], Some(dup_doc))?;
    assert_eq!(code, 0, "`.,.` should not raise since #2103, stderr: {err}");
    assert!(err.is_empty(), "`.,.` stderr should be empty, got: {err}");
    assert_eq!(
        out,
        format!("{dup_doc}\n{dup_doc}\n"),
        "`.,.` should echo the raw source bytes twice"
    );

    // A single decode-failure key still preserves fine under the same
    // routes -- no false positive from the new guard.
    let single_doc = r#"{"\ud800":1,"b":2}"#;
    let (out, err, code) = run_jq_full(&["-Sc", "."], Some(single_doc))?;
    assert_eq!(
        code, 0,
        "single bad key should still succeed, stderr: {err}"
    );
    assert_eq!(out.trim(), "{\"\\\\ud800\":1,\"b\":2}");

    // An ordinary repeated key -- no decode failure on either side -- still
    // collapses to the last value (jq's normal duplicate-key handling); the
    // guard must not turn a genuine duplicate into a raise.
    let ordinary_dup = r#"{"a":1,"a":2}"#;
    let (out, err, code) = run_jq_full(&["-Sc", "."], Some(ordinary_dup))?;
    assert_eq!(
        code, 0,
        "ordinary duplicate key should not raise, stderr: {err}"
    );
    assert_eq!(out.trim(), "{\"a\":2}");

    Ok(())
}

/// #2103: `eval_each_pipe_generic`'s empty-`exprs` tail used to drop
/// `cursor` and fall back to `GenericItem::One(value)` on the theory (its
/// old comment, removed by this fix) that an empty `Expr::Pipe` "never
/// actually reaches zero length in practice." It does: a bare
/// `keys_unsorted[]` drives `each_lazy_keys_iterate_sink`'s streaming
/// `!sorted` arm (#1565/#1770), whose `rest` is `[]`, and every key lands
/// here via `continue_pipe_element_generic`'s `OneCursorValue` arm with
/// `cursor = Some(_)`. Dropping the cursor forced a second, *validating*
/// decode of the key on the way back out -- for an undecodable key (a lone
/// UTF-16 surrogate `\ud800`, or an invalid `\q` escape) that raised on the
/// demand-driven (streaming) evaluator where the eager/materializing route
/// already echoed the raw source bytes verbatim, per the #1247/#1385/#1642
/// preservation rule. The fix re-pairs `cursor` with the already-decoded
/// `value` into `GenericItem::OneCursorValue` (#1609's variant, reused
/// rather than re-decoded) instead of discarding the cursor, so nothing
/// forces that second decode.
///
/// The raw spelling, not a `\uXXXX`-normalized one, is the correct
/// expectation: the value is never materialized on this path (that's the
/// whole point of streaming), so what comes back out is whatever the
/// source bytes were.
///
/// `limit(2; keys_unsorted[])` is included alongside the bare `.[]` form
/// since it exercises the same `rest == []` arm through a different
/// consumer.
///
/// This used to also cross-check against the eager route via
/// `SUCCINCTLY_JQ_M2_EVAL=eager` (`run_jq_full_env`); that route and the env
/// var were deleted once #2103's phase 3 made streaming the only M2 route,
/// so this now just pins the shipped output through `run_jq_full`.
#[test]
fn test_streaming_keys_unsorted_iterate_echoes_undecodable_key_raw_2103() -> Result<()> {
    let cases = [
        (r#"{"\ud800":1,"b":2}"#, "\"\\ud800\"\n\"b\"\n"),
        (r#"{"a\q":1,"b":2}"#, "\"a\\q\"\n\"b\"\n"),
    ];

    for (doc, expected) in cases {
        for filter in ["keys_unsorted[]", "limit(2; keys_unsorted[])"] {
            let (out, err, code) = run_jq_full(&[filter], Some(doc))?;
            assert_eq!(
                code, 0,
                "doc {doc:?}, filter {filter:?}: should not raise, stderr: {err}"
            );
            assert!(
                err.is_empty(),
                "doc {doc:?}, filter {filter:?}: stderr should be empty, got: {err}"
            );
            assert_eq!(
                out, expected,
                "doc {doc:?}, filter {filter:?}: should echo the raw source spelling"
            );
        }
    }

    Ok(())
}

/// #2103: every M2 filter streams, and **a filter validates only what it
/// reads**.
///
/// What the eager route did: `eval_single`'s wildcard arm materialized the
/// ambient value through `to_owned_with_cursor` before evaluating anything,
/// and that one call was doing two jobs beyond producing a value --
/// validating the whole document (#1194's structural checks, #1642's
/// colliding-display-key raise) and choosing an undecodable key's spelling.
/// The M2 route was gated to keep any filter whose eager twin was that
/// wildcard off the demand-driven evaluator, precisely so the two routes
/// could not disagree about whether a document was acceptable.
///
/// Why that was an accident, not a decision: nobody chose that `1+1` should
/// validate its input. The check fired because the bridge needed an
/// `OwnedValue` to hand to `eval.rs`, and only for the spellings that
/// happened to reach the wildcard -- so on `{"\ud800":1,"\ud800":2}` one
/// binary answered `.`, `.b`, `length`, `keys` and `label $x | .` at exit 0
/// while `.,.`, `1+1`, `debug` and `if . then . else . end` exited 5. That
/// "the spelling of the filter decides whether the document is valid" shape
/// is what #1629/#1642/#2168 exist to remove.
///
/// The rule, inherited verbatim from #2168's entry: a filter that navigates
/// to a position validates only what it reads; one that materializes
/// validates everything it materializes. `1+1` and `try (1+1)` read nothing,
/// so they validate nothing and answer `2`. `.,.` forwards the root cursor
/// to the printer, which walks it exactly as `.` does -- so a *structural*
/// fault is still found where the walk reaches it (the `{123:1,"b":2}`
/// control below still exits 5 under `.,.`, as under `.`), while a colliding
/// undecodable key, which the walk never has to resolve, is echoed raw.
/// `-S`/`-s` still raise on that document, because building one
/// `String`-keyed map out of both keys is what the collision *is*.
///
/// **jq 1.7.1's answer is exit 5 on every row in the first table**, captured
/// live from the pinned `/usr/bin/jq`: it is a full validating parser and
/// rejects each of these documents before any filter runs (`Object keys must
/// be strings`, `Objects must consist of key:value pairs`, `Invalid numeric
/// literal`, `Expected separator between values`, `Expected value before
/// ','`, `Invalid \uXXXX\uXXXX surrogate pair escape`). So this is a
/// deliberate divergence taken against ADR-0018's decision order -- step 2
/// separates the options and favours the behaviour being given up -- and it
/// is recorded on its merits in `docs/compliance/jq/limitations.md` under
/// "Every M2 filter streams", alongside #2168's entry. A user who wants
/// jq's rejection has `--validate` and `succinctly json validate`.
///
/// The controls in the second half are what make this test discriminate
/// rather than merely record: if the change had disabled document
/// validation wholesale instead of moving it behind what the filter reads,
/// `.`, `length` and `.,.` on `{123:1,"b":2}` and `-S .` on the colliding
/// document would all have stopped raising too.
#[test]
fn test_root_forwarding_filters_stream_without_validating_2103() -> Result<()> {
    // Reads nothing, so validates nothing -- on every malformed shape the
    // codebase keeps deliberately distinct (#1194 non-string key, #1194
    // unpaired tail, #1194 malformed tail member, #1677 missing `:`, #1597
    // stray `,`) plus #1642's colliding undecodable keys. jq: exit 5, all 18.
    for doc in [
        r#"{123:1,"b":2}"#,
        r#"{"a":1,"b"}"#,
        r#"{"a":1, invalid}"#,
        r#"{"a" 1, "b":2}"#,
        r"[1,,3]",
        r#"{"\ud800":1,"\ud800":2}"#,
    ] {
        for filter in ["1+1", "try (1+1)", r#"try (1+1) catch "x""#] {
            let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
            assert_eq!(code, 0, "doc {doc:?} filter {filter:?}, stderr: {err}");
            assert!(
                err.is_empty(),
                "doc {doc:?} filter {filter:?}, stderr: {err}"
            );
            assert_eq!(out, "2\n", "doc {doc:?} filter {filter:?}");
        }
    }

    // The 19th row: `.,.` on the colliding document forwards the root
    // cursor to the printer twice and never builds the map the collision is
    // about. jq: exit 5.
    let dup_doc = r#"{"\ud800":1,"\ud800":2}"#;
    let (out, err, code) = run_jq_full(&["-c", ".,."], Some(dup_doc))?;
    assert_eq!(code, 0, "`.,.` on {dup_doc:?}, stderr: {err}");
    assert!(err.is_empty(), "`.,.` on {dup_doc:?}, stderr: {err}");
    assert_eq!(out, format!("{dup_doc}\n{dup_doc}\n"));

    // --- Controls: these must NOT have moved. ---

    // A structural fault is still found by the walk that reaches it, for
    // every filter that actually reads the document -- `.,.` included,
    // because the printer walks the root cursor it was handed.
    let malformed = r#"{123:1,"b":2}"#;
    for filter in [".", "length", ".,."] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(malformed))?;
        assert_eq!(code, 5, "filter {filter:?} must still raise, out: {out:?}");
        assert!(
            err.contains("Invalid JSON text"),
            "filter {filter:?}, stderr: {err}"
        );
    }

    // Materializing into one `String`-keyed map still raises on the
    // collision -- the #1642 guard is untouched.
    let (out, err, code) = run_jq_full(&["-Sc", "."], Some(dup_doc))?;
    assert_eq!(code, 5, "`-S .` must still raise, out: {out:?}");
    assert!(err.contains("ambiguous"), "stderr: {err}");

    // --- Spelling: raw where nothing materializes, doubled where it does. ---

    // `.,.` echoes the source bytes, exactly as `.` does.
    let single_doc = r#"{"\ud800":1,"b":2}"#;
    let (out, err, code) = run_jq_full(&["-c", ".,."], Some(single_doc))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert!(err.is_empty(), "stderr: {err}");
    assert_eq!(out, format!("{single_doc}\n{single_doc}\n"));

    // `(., debug)` gets *both* spellings out of one filter, and that is
    // consistent under the rule rather than a third spelling: `.` forwards
    // the cursor (raw), while `debug` materializes its input to build the
    // `["DEBUG:", ...]` message and then forwards what it built (doubled),
    // on stdout as well as stderr.
    let (out, err, code) = run_jq_full(&["-c", "(., debug)"], Some(single_doc))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(
        out,
        concat!(
            r#"{"\ud800":1,"b":2}"#,
            "\n",
            r#"{"\\ud800":1,"b":2}"#,
            "\n"
        )
    );
    assert_eq!(err, concat!(r#"["DEBUG:",{"\\ud800":1,"b":2}]"#, "\n"));

    Ok(())
}

/// #3035: a keyword token is exactly `true`/`false`/`null` -- a prefix
/// (`nullx`, `truex`, `falsey`) or a truncated one (`nul`, `tru`, `fals`)
/// is jq's `Invalid literal` (`/usr/bin/jq 1.7.1`: exit 5 for every row
/// below), and succinctly must not decode `null`/`true`/`false` "out of the
/// middle" of such a token. Every row asserts exit 5 *and* empty stdout: a
/// bite-sized literal printed before the raise is exactly the leak. The
/// valid keywords in the second half are the controls that must stay alive.
#[test]
fn test_keyword_prefix_and_truncated_tokens_reject_3035() -> Result<()> {
    for doc in [
        "nullx", "truex", "falsey", "nul", "tru", "fals", "nully", "null1", "true_", "falsee",
    ] {
        let (out, err, code) = run_jq_full(&["."], Some(doc))?;
        assert_eq!(code, 5, "top-level {doc:?} `.` must reject, out: {out:?}");
        assert!(
            out.is_empty(),
            "top-level {doc:?} `.` must leak nothing, out: {out:?}"
        );
        assert!(
            err.contains("Invalid JSON text"),
            "top-level {doc:?} `.`, stderr: {err}"
        );

        let (out, _, code) = run_jq_full(&["type"], Some(doc))?;
        assert_eq!(
            code, 5,
            "top-level {doc:?} `type` must reject, out: {out:?}"
        );
        assert!(
            out.is_empty() || !out.contains("error"),
            "top-level {doc:?} `type` must not answer internally, out: {out:?}"
        );

        let (out, _, code) = run_jq_full(&["-c", "."], Some(doc))?;
        assert_eq!(
            code, 5,
            "top-level {doc:?} `-c .` must reject, out: {out:?}"
        );
        assert!(
            out.is_empty(),
            "top-level {doc:?} `-c .` must leak nothing, out: {out:?}"
        );
    }

    // Controls: exact keywords still decode and answer.
    for (doc, want) in [("null", "null"), ("true", "true"), ("false", "false")] {
        let (out, err, code) = run_jq_full(&["-c", "."], Some(doc))?;
        assert_eq!(code, 0, "{doc:?} control, stderr: {err}");
        assert_eq!(out, format!("{want}\n"), "{doc:?} control");
    }
    let (out, err, code) = run_jq_full(&["-c", "type"], Some("true"))?;
    assert_eq!(code, 0, "`type` on true, stderr: {err}");
    assert_eq!(out, "\"boolean\"\n");
    Ok(())
}

/// #3035: the same whole-token rule inside containers, on the paths the
/// issue's tables pin -- a bare identity, a field access that reaches the
/// malformed value, and every `type`-family filter that iterates the bad
/// element. All 27 rows match `/usr/bin/jq 1.7.1`'s exit 5 on the same
/// input.
#[test]
fn test_keyword_errors_inside_containers_3035() -> Result<()> {
    for (doc, queries) in [
        (
            "[nullx]",
            vec!["-c .", "-c map(.)", "-c map(type)", "-c .[]|type"],
        ),
        (
            "[nul]",
            vec!["-c .", "-c map(.)", "-c map(type)", "-c .[]|type"],
        ),
        ("[tru,false]", vec!["-c .", "-c map(.)", "-c map(type)"]),
        ("[truex]", vec!["-c .", "-c map(type)", "-c .[]|type"]),
        ("[nullx,\"ok\"]", vec!["-c .", "-c map(.)", "-c map(type)"]),
        (
            "{\"a\":nullx}",
            vec![".a", "-c .", "-c map(.)", "-c map(type)"],
        ),
        ("{\"a\":nul}", vec![".a", "-c map(type)"]),
        ("{\"a\":[nullx]}", vec![".a", "-c map(.)"]),
    ] {
        for q in queries {
            let args: Vec<&str> = q.split_whitespace().collect();
            let (out, _, code) = run_jq_full(&args, Some(doc))?;
            assert_eq!(code, 5, "doc {doc:?} query `{q}` must reject, out: {out:?}");
            // Streaming may have emitted a partial prefix of the container
            // (`{"a":` for the object) before the malformed member raised --
            // that is #2961's incremental behavior, not a leak. What must
            // never appear is a *decoded bite* of the malformed keyword.
            assert!(
                !matches!(out.trim(), "null" | "true" | "false" | "nan"),
                "doc {doc:?} query `{q}` decoded a bite of the token: {out:?}"
            );
        }
    }

    // Controls: the same shapes stay healthy when the keyword is exact.
    let (out, err, code) = run_jq_full(&["-c", "."], Some("[null,true,false]"))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out, "[null,true,false]\n");
    let (out, err, code) = run_jq_full(&["-c", "map(type)"], Some("[null,true,false]"))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out, "[\"null\",\"boolean\",\"boolean\"]\n");
    let (out, err, code) = run_jq_full(&[".a"], Some("{\"a\":null,\"b\":1}"))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out, "null\n");
    Ok(())
}

/// #3035: the `type` builtin must raise where the malformed keyword token
/// *is* `type`'s input -- not answer the internal `"error"` value name.
/// Exercised across the lazy routes (`-c`, `-S`, `-a`, `-e`, `-s`) that
/// each had the leak pre-fix.
#[test]
fn test_type_raises_on_malformed_keyword_instead_of_error_name_3035() -> Result<()> {
    // Top level, `nul` is the whole input, so `type`'s input is the error
    // value itself and every route must raise.
    for filter in [
        "type", "-c type", "-S type", "-a type", "-e type", "-s type",
    ] {
        let args: Vec<&str> = filter.split_whitespace().collect();
        let (out, err, code) = run_jq_full(&args, Some("nul"))?;
        assert_eq!(
            code, 5,
            "`{filter}` on `nul` must raise, out: {out:?}, stderr: {err}"
        );
    }
    // Nested: only the iterating forms hand `type` the element that *is* the
    // error. (`[nul] | type` legitimately answers `"array"` without
    // descending -- a malformed child a filter never reads is the
    // pre-existing lazy-streaming divergence, not this bug -- but `.[]`
    // chooses the element, so `.[]|type` reaches it exactly as `type` on
    // the top-level `nul` does.)
    let (out, err, code) = run_jq_full(&["-c", "map(type)"], Some("[nul]"))?;
    assert_eq!(
        code, 5,
        "`map(type)` on `[nul]` must raise, out: {out:?}, stderr: {err}"
    );
    let (out, err, code) = run_jq_full(&["-c", ".[]|type"], Some("[nul]"))?;
    assert_eq!(
        code, 5,
        "`.[]|type` on `[nul]` must raise, out: {out:?}, stderr: {err}"
    );
    // The same filters on healthy input still answer.
    let (out, err, code) = run_jq_full(&["type"], Some("true"))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out, "\"boolean\"\n");
    let (out, err, code) = run_jq_full(&["-c", ".[]|type"], Some("[true,null]"))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out, "\"boolean\"\n\"null\"\n");
    Ok(())
}

/// #2103 (code review) / #2662: the decision that a filter validates only
/// what it reads is a property of the M2 route, and the M2 route was not
/// the only one -- `-S`, `-a`, `-s`, `-C` and the `-n`/`input` bridge all
/// went through `evaluate_input_streaming`, which materialized the whole
/// input into an `OwnedValue` *before* evaluating, so `1+1` on a malformed
/// document exited 5 on every one of them where the default route already
/// answered `2`. #2662 closed that gap for `-S`/`-a`/`-C` (moved onto the
/// same lazy route the default already used) but deliberately left `-s`
/// and `-n`/`input` materializing -- `-s` needs a real offset-mapping
/// redesign (tracked, not yet done) and `input` must hand the evaluator a
/// value it can return from a builtin, which requires materializing by
/// construction (#2662's own triage, not an oversight). `-e` streams like
/// the default but materializes each *output* to decide the exit status,
/// so `-e '.,.'` on the colliding-key document still raises where `-c
/// '.,.'` echoes -- unchanged by #2662, `-e` was never one of the flags
/// moved. Every exit-5 row here matches jq 1.7.1's own parse-time
/// rejection; the exit-0 rows for `-s`/`-n` are the recorded, still-open
/// #2103 divergence for those two routes specifically now.
#[test]
fn test_materializing_flag_routes_still_validate_2103() -> Result<()> {
    let structural = r#"{123:1,"b":2}"#;
    let colliding = r#"{"\ud800":1,"\ud800":2}"#;

    for doc in [structural, colliding] {
        for filter in ["1+1", r#"try (1+1) catch "x""#] {
            // The default route: the #2103 divergence.
            let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
            assert_eq!(
                (out.as_str(), code),
                ("2\n", 0),
                "{filter} on {doc}: stderr {err}"
            );

            // #2662: `-S`/`-a`/`-C` moved onto the same lazy route as the
            // default -- `1+1` reads nothing from the document, so all
            // three now answer the same way the default route does,
            // malformed document and all. `-c` prefix keeps output
            // comparable across rows. Exact matches, not a substring check
            // -- `doc` itself contains the digit `2` (`"b":2`), so a
            // substring check couldn't distinguish the filter's own answer
            // from a leaked fragment of the unread document.
            for (flags, want) in [
                (&["-Sc"][..], "2\n"),
                (&["-ac"], "2\n"),
                (&["-Cc"], "\u{1b}[0;39m2\u{1b}[0m\n"),
            ] {
                let mut args = flags.to_vec();
                args.push(filter);
                let (out, err, code) = run_jq_full(&args, Some(doc))?;
                assert_eq!(
                    (out.as_str(), code),
                    (want, 0),
                    "{flags:?} {filter} on {doc}: stderr {err}"
                );
            }

            // `-s` still materializes -- unmoved by #2662, see this test's
            // own doc comment.
            let (out, err, code) = run_jq_full(&["-sc", filter], Some(doc))?;
            assert_eq!(code, 5, "-s {filter} on {doc}: out {out:?} stderr {err}");
            assert!(out.is_empty(), "-s {filter} on {doc}: out {out:?}");

            // `-n`/`input` still materializes what it reads -- also
            // unmoved, and correctly so per #2662's own analysis (`input`
            // must hand the evaluator an owned value it can return from a
            // builtin).
            let bridged = format!("input | {filter}");
            let (out, err, code) = run_jq_full(&["-nc", &bridged], Some(doc))?;
            assert_eq!(code, 5, "-n {bridged} on {doc}: out {out:?} stderr {err}");
            assert!(out.is_empty(), "-n {bridged} on {doc}: out {out:?}");
        }
    }

    // `-e` materializes the outputs, not the input: `1+1` answers, `.,.`
    // (whose output *is* the colliding document) raises.
    let (out, _, code) = run_jq_full(&["-ce", "1+1"], Some(colliding))?;
    assert_eq!((out.as_str(), code), ("2\n", 0));
    let (out, err, code) = run_jq_full(&["-ce", ".,."], Some(colliding))?;
    assert_eq!(code, 5, "out {out:?} stderr {err}");
    assert!(err.contains("ambiguous"), "stderr: {err}");
    let (out, _, code) = run_jq_full(&["-c", ".,."], Some(colliding))?;
    assert_eq!(code, 0, "control: the default route echoes, out {out:?}");

    Ok(())
}

/// #2662: well-formed output for `-S`/`-a`/`-C` is unaffected by moving
/// them onto the lazy route -- each still produces the exact same bytes
/// as before (and as real jq), just without materializing the whole
/// document first. Confirmed live against jq 1.7.1 for every row.
#[test]
fn test_sort_ascii_color_output_unaffected_by_lazy_route_move_2662() -> Result<()> {
    let (out, err, code) = run_jq_full(&["-Sc", "."], Some(r#"{"b":1,"a":2,"c":3}"#))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out.trim(), r#"{"a":2,"b":1,"c":3}"#);

    let (out, err, code) = run_jq_full(&["-ac", "."], Some(r#"{"a":"café"}"#))?;
    assert_eq!(code, 0, "stderr: {err}");
    // `é` (U+00E9) escaped as `é`, not the literal UTF-8 byte -- that
    // is the point of `-a`. Confirmed live against jq 1.7.1.
    assert_eq!(out.trim(), "{\"a\":\"caf\\u00e9\"}");

    let (out, err, code) = run_jq_full(&["-Cc", "."], Some(r#"{"a":1}"#))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert!(
        out.contains("\x1b["),
        "-C must still emit ANSI codes: {out:?}"
    );
    assert!(out.contains('1'), "out: {out:?}");

    Ok(())
}

/// #2662: `-a` wins over `-r` for a *string* value -- confirmed live
/// against jq 1.7.1 (`-acr '"café"'` prints `"café"`, quoted and escaped,
/// not the unquoted raw string `-r` alone gives). A non-string value is
/// unaffected either way. Pinned on both the lazy route (`-S`/`-a`/`-C`,
/// moved by this issue) and the still-materializing `-s` route, since both
/// `write_output_jq_value` and `write_output` had the identical gap before
/// this fix.
#[test]
fn test_ascii_output_wins_over_raw_for_strings_2662() -> Result<()> {
    // `-acr`: the lazy route (`write_output_jq_value`, moved by this issue).
    let (out, err, code) = run_jq_full(&["-acr", "."], Some(r#""café""#))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(
        out.trim(),
        "\"caf\\u00e9\"",
        "-a must still quote+escape a string even under -r"
    );

    // `-acsr`: the still-materializing `-s` route (`write_output`), wrapped
    // in slurp's own array -- same escaping fix, different writer.
    let (out, err, code) = run_jq_full(&["-acsr", "."], Some(r#""café""#))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out.trim(), "[\"caf\\u00e9\"]");

    // A non-string value is unaffected by `-a`/`-r` either way.
    let (out, err, code) = run_jq_full(&["-acr", "."], Some("42"))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out.trim(), "42");

    Ok(())
}

/// #2662 (a second bug found by review, on top of the quoting fix above):
/// `--seq`'s RS-separator byte must key on whether `-r` alone would have
/// made this value raw -- a string, full stop -- not on whether `-a` later
/// overrode that shaping back to quoted+escaped. Confirmed live against jq
/// 1.7.1: `--seq -acr` on a string suppresses the RS byte exactly as plain
/// `--seq -r` does, even though the printed bytes end up quoted+escaped
/// either way; `--seq -r` on a *non-string* value (where `-r` has no effect
/// on shape at all) keeps the RS byte. An earlier revision of the quoting
/// fix above keyed the RS decision off the post-override write instead,
/// which emitted a spurious RS byte under `--seq -acr` on a string.
#[test]
fn test_seq_separator_keys_on_pre_ascii_override_raw_shape_2662() -> Result<()> {
    // `\u{1e}` (RS) prefix on stdin: `--seq`'s own input-framing convention.
    for (args, input, want) in [
        (
            &["--seq", "-acr", "."][..],
            "\u{1e}\"café\"\n",
            "\"caf\\u00e9\"\n",
        ),
        (&["--seq", "-r", "."][..], "\u{1e}42\n", "\u{1e}42\n"),
        (&["--seq", "-r", "."][..], "\u{1e}\"hello\"\n", "hello\n"),
        (
            &["--seq", "."][..],
            "\u{1e}\"hello\"\n",
            "\u{1e}\"hello\"\n",
        ),
    ] {
        let (out, err, code) = run_jq_full(args, Some(input))?;
        assert_eq!(code, 0, "{args:?} on {input:?}: stderr {err}");
        assert_eq!(out, want, "{args:?} on {input:?}");
    }

    Ok(())
}

/// #2662: a malformed document reached during `-S`/`-a`/`-C`'s own
/// materialize-the-output step must still report through jq's diagnostic
/// channel (exit 5, `jq: error (at ...)`), not fall through to a bare
/// `anyhow` failure (exit 1, `Error: ...`) the way it did before this fix
/// -- the gap was in `write_output_jq_value` itself, only ever exercised
/// once `-S`/`-a`/`-C` could reach the lazy path at all.
#[test]
fn test_malformed_document_error_channel_under_lazy_sort_ascii_color_2662() -> Result<()> {
    for flags in [&["-Sc"][..], &["-ac"], &["-Cc"]] {
        let mut args = flags.to_vec();
        args.push(".");
        let (out, stderr, code) = run_jq_full(&args, Some("{invalid}"))?;
        assert_eq!(code, 5, "{flags:?}: out {out:?} stderr {stderr:?}");
        assert!(
            stderr.starts_with("jq: error"),
            "{flags:?} must report in jq's channel, not anyhow's: {stderr:?}"
        );
    }

    Ok(())
}

/// #2103 (code review, finding 1): the empty-pipe cursor fix (commit 1) and
/// the gate deletion (commit 2) also moved two *value*-position spellings,
/// not just the object-key `keys_unsorted[]` case commit 1 was filed for.
/// On `[{"x":"\ud800"}]` -- an element whose `.x` is a lone high surrogate,
/// which real jq rejects at parse time for *every* spelling -- `first(map(.x)
/// | .[])` moved 5 -> 0 at commit 1 and `limit(1; map(.x) | .[])` at commit
/// 2, both now echoing the raw source bytes at exit 0.
///
/// This is the same divergence the rest of #2103 records, reaching two more
/// spellings, not a new one -- and restoring validation here would *undo*
/// #2168's rule rather than uphold it. succinctly echoes a decode-failure
/// value raw on navigation and degrades/raises only on materialization
/// (`docs/plan/decode-failure-routing.md`); on this document `.[].x`,
/// `first(.[].x)` and `map(.x) | .[]` already echoed at exit 0 on `main`
/// and on `baa26d72e`, while `map(.x)` alone (which materializes the array)
/// raised. Only `first`/`limit` *wrapping* the fused `map(.x) | .[]` stream
/// used to fall to a materializing path and raise -- so `main` echoed
/// `map(.x) | .[]` but raised `first(map(.x) | .[])` on one document, the
/// exact spelling-dependence #1629/#1642/#2168 exist to remove. These rows
/// make the two consistent with the navigation they wrap; the value is
/// echoed byte-identically to `.[].x`.
///
/// Attribution verified by building `baa26d72e` (commit 1's parent) and
/// `main` (`4b1ebba80`, which carries #965's key-decode rewrite): both raise
/// `first(map(.x) | .[])`, so #965 is not the cause and the move is this
/// PR's -- recorded rather than absorbed.
#[test]
fn test_first_limit_echo_a_decode_failure_value_like_navigation_2103() -> Result<()> {
    let doc = r#"[{"x":"\ud800"}]"#;
    let raw = "\"\\ud800\"\n";

    // Controls, echoing on every binary since before this PR -- navigation
    // to a decode-failure value emits it raw, it is not materialized.
    for filter in [".[].x", "first(.[].x)", "map(.x) | .[]"] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_eq!((out.as_str(), code), (raw, 0), "{filter}: stderr {err}");
    }

    // The two spellings this PR moved: `first`/`limit` over the fused
    // `map(.x) | .[]` stream now echo the same value, instead of raising.
    for filter in ["first(map(.x) | .[])", "limit(1; map(.x) | .[])"] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_eq!((out.as_str(), code), (raw, 0), "{filter}: stderr {err}");
    }

    // `map(.x)` alone still materializes the array and so still validates --
    // unchanged, and the boundary that keeps this a navigation rule, not a
    // blanket "never validate a value" one.
    let (out, _err, code) = run_jq_full(&["-c", "map(.x)"], Some(doc))?;
    assert_eq!(code, 5, "map(.x) must still raise: out {out:?}");
    assert!(out.is_empty());

    // The invalid-escape value variant echoes raw the same way.
    let (out, err, code) = run_jq_full(&["-c", "first(map(.x) | .[])"], Some(r#"[{"x":"a\q"}]"#))?;
    assert_eq!((out.as_str(), code), ("\"a\\q\"\n", 0), "stderr {err}");

    Ok(())
}

/// #1813: `colliding_display_key_error` (#1642) is built via
/// `EvalError::decode_failure`, whose contract says the result "must never
/// be suppressed by `?` or caught by `try`/`catch`" -- but `is_decode_failure`
/// classified purely by matching `message` against a fixed literal list that
/// didn't include this error's dynamic ("object key \"<key>\" is
/// ambiguous: ...") text, so both `?` and `try`/`catch` treated it as an
/// ordinary catchable error. Confirmed live before this fix: `sort?`
/// silently produced no output at exit 0, and `try sort catch .` returned
/// the message as a caught value instead of letting it escape.
#[test]
fn test_colliding_display_key_error_is_uncatchable_1813() -> Result<()> {
    let dup_doc = r#"[{"\ud800":1,"\ud800":2}]"#;

    let (out, err, code) = run_jq_full(&["sort?"], Some(dup_doc))?;
    assert_ne!(
        code, 0,
        "`?` must not silently suppress a colliding-key error, out: {out:?}"
    );
    assert!(err.contains("ambiguous"), "stderr: {err}");

    let (out, err, code) = run_jq_full(&["try sort catch ."], Some(dup_doc))?;
    assert_ne!(
        code, 0,
        "try/catch must not catch a colliding-key error, out: {out:?}"
    );
    assert!(err.contains("ambiguous"), "stderr: {err}");

    // `delpaths(...)?` specifically, called out by the issue: #1746 review
    // added an `is_uncatchable()`-gated suppression bypass there.
    let dup_obj = r#"{"\ud800":1,"\ud800":2}"#;
    let (out, err, code) = run_jq_full(&["delpaths([[\"a\"]])?"], Some(dup_obj))?;
    assert_ne!(
        code, 0,
        "delpaths(...)? must not silently suppress a colliding-key error, out: {out:?}"
    );
    assert!(err.contains("ambiguous"), "stderr: {err}");

    Ok(())
}

/// #1813 companion: a user's own `error(...)` call, even with the exact
/// suffix text `is_decode_failure` also recognizes as a genuine decode
/// failure, must stay ordinarily catchable. `is_decode_failure()` checks
/// `EvalErrorPayload::Kind(ErrorKind::DecodeFailure)` (#1840) -- `error(v)`
/// sets `EvalErrorPayload::Value(v)` instead, a distinct enum variant no
/// `Kind`-matching arm can ever match regardless of `v`'s content -- so this
/// user error can never be misclassified as a decode failure no matter what
/// text it carries.
#[test]
fn test_user_error_matching_colliding_key_suffix_stays_catchable_1813() -> Result<()> {
    let filter = r#"try error("object key \"x\" is ambiguous: an undecodable key's display form collides with another key of the same name and cannot be represented") catch ("caught: " + .)"#;
    let (out, err, code) = run_jq_full(&[filter], Some("null"))?;
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(
        out.trim(),
        "\"caught: object key \\\"x\\\" is ambiguous: an undecodable key's display form collides with another key of the same name and cannot be represented\""
    );
    Ok(())
}

/// #1642 follow-up: `-e`/`--exit-status` forces `JqValue::materialize()` on
/// every result before `jq_runner.rs`'s own guarded `print_json` path ever
/// runs (see `cursor_to_owned`'s doc comment in `src/jq/lazy.rs`) -- a
/// second, independent materializer from the `-S`/`-s`/`.,.`  routes the
/// test above covers, with its own `DisplayKeyGuard` call site that a fix
/// touching only the other three left unexercised. Without `-e`, the same
/// document streams both colliding keys through untouched (#1385: a
/// decode-failure key is never a duplicate, so nothing raises); `-e` alone
/// is what forces the raise.
#[test]
fn test_exit_status_materialize_route_raises_on_colliding_decode_failure_keys_1642() -> Result<()> {
    let dup_doc = r#"{"\ud800":1,"\ud800":2}"#;

    let (out, code) = run_jq_stdin(".", dup_doc, &["-c"])?;
    assert_eq!(code, 0, "no -e: both keys should stream through untouched");
    assert_eq!(out.trim(), r#"{"\ud800":1,"\ud800":2}"#);

    let (out, err, code) = run_jq_full(&["-e", "-c", "."], Some(dup_doc))?;
    assert_ne!(
        code, 0,
        "-e should raise rather than silently drop a value, out: {out:?}"
    );
    assert!(err.contains("ambiguous"), "stderr: {err}");

    Ok(())
}

/// #1514: `keys_unsorted | map(f)` and `keys_unsorted | .[]` no longer probe
/// the whole object before the first key comes out — they dedup as they walk
/// and switch to the exact collapsed list only once a hash repeats. That
/// switch has to resume at the right offset, so a duplicate in the *middle*
/// of a wide object is the shape that matters: keys before it have already
/// been emitted and must not repeat, keys after it must all still arrive.
///
/// The object is wider than the printer's `PAIRWISE_SPAN_SCAN_LIMIT` so the
/// hash-table branch is the one under test, not the small-object pairwise
/// scan.
#[test]
fn test_lazy_keys_dedup_switches_mid_walk_1514() -> Result<()> {
    const HEAD: usize = 30;
    const TAIL: usize = 30;
    let mut input = String::from("{");
    for i in 0..HEAD {
        input.push_str(&format!("\"m{i}\":{i},"));
    }
    input.push_str("\"m5\":-1,");
    for i in 0..TAIL {
        input.push_str(&format!("\"n{i}\":{i},"));
    }
    input.pop();
    input.push('}');

    let expected_keys: Vec<String> = (0..HEAD)
        .map(|i| format!("\"m{i}\""))
        .chain((0..TAIL).map(|i| format!("\"n{i}\"")))
        .collect();
    let expected_array = format!("[{}]", expected_keys.join(","));

    for filter in ["keys_unsorted|map(.)", "[keys_unsorted[]]"] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(&input))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(
            out.trim(),
            expected_array,
            "filter {filter}: the repeat of m5 collapses to its first position \
             and every later key still arrives"
        );
    }

    // The positional and counting arms have to agree with the streamed ones.
    for (filter, expected) in [
        ("keys_unsorted|length", (HEAD + TAIL).to_string()),
        ("keys_unsorted|first", "\"m0\"".to_string()),
        ("keys_unsorted|last", format!("\"n{}\"", TAIL - 1)),
        ("keys_unsorted[5]", "\"m5\"".to_string()),
        ("keys_unsorted[-1]", format!("\"n{}\"", TAIL - 1)),
        (".m5", "-1".to_string()),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(&input))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    Ok(())
}

/// #1514: an object whose keys *all* repeat drives the mid-walk switch on
/// the very first duplicate, when exactly one key has gone out. Guards the
/// resume offset against an off-by-one that a tail-duplicate case cannot
/// see.
#[test]
fn test_lazy_keys_dedup_switches_on_the_second_field_1514() -> Result<()> {
    let input = r#"{"a":1,"a":2,"a":3,"b":4}"#;
    for (filter, expected) in [
        ("keys_unsorted|map(.)", r#"["a","b"]"#),
        ("[keys_unsorted[]]", r#"["a","b"]"#),
        ("keys_unsorted|length", "2"),
        (".", r#"{"a":3,"b":4}"#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }
    Ok(())
}

/// #1514 review: `keys_unsorted | .[n]` and `keys_unsorted | last` must keep
/// folding the *rest* of the pipe once they've resolved positionally against
/// the collapsed list on a duplicate-keyed object. Both arms briefly used
/// `return` inside `fold_pipe_stages`'s per-stage `match`, which exits the
/// whole function instead of handing the value to the next stage — silently
/// dropping every filter chained after the index/`last`. Only reachable when
/// the object has a genuine duplicate key: the collapsed branch is untaken
/// otherwise, which is why the plain no-duplicate case must be pinned here
/// too, not just the buggy one.
#[test]
fn test_lazy_keys_index_and_last_continue_the_pipe_on_duplicates_1514() -> Result<()> {
    let dup = r#"{"b":1,"a":2,"b":3}"#;
    for (filter, expected) in [
        ("keys_unsorted|.[0]|length", "1"),
        ("keys_unsorted|.[-1]|length", "1"),
        ("keys_unsorted|last|length", "1"),
        ("keys_unsorted|.[0]|ascii_upcase", r#""B""#),
        ("keys_unsorted|last|ascii_upcase", r#""A""#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(dup))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(
            out.trim(),
            expected,
            "filter {filter}, duplicate-keyed input"
        );
    }

    let clean = r#"{"x":1,"y":2}"#;
    for (filter, expected) in [
        ("keys_unsorted|.[0]|length", "1"),
        ("keys_unsorted|last|length", "1"),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(clean))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(
            out.trim(),
            expected,
            "filter {filter}, no-duplicate control"
        );
    }

    Ok(())
}

/// #1385 review: `--preserve-input` preserves duplicate keys on *output*
/// and nowhere else. The exemption ADR-0018 rule 5 grants that extension
/// reaches the printer, which is gated on `jq_compat`; the evaluator is
/// gated on `JqSemantics::COLLAPSE_DUPLICATE_KEYS`, a const the flag cannot
/// reach. Both halves are pinned here so the split stays a documented
/// contract rather than drifting into a silent inconsistency.
///
/// It is the same split the flag already has for numbers, asserted below:
/// `4e4` is echoed as written while `. + 0` evaluates it.
#[test]
fn test_preserve_input_duplicate_keys_are_output_only_1385() -> Result<()> {
    let input = r#"{"b":1,"a":2,"b":3}"#;

    // Output: every occurrence, at the top level and nested.
    let (out, _, code) = run_jq_full(&["-c", "--preserve-input", "."], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), input);

    let (nested, _, code) = run_jq_full(
        &["-c", "--preserve-input", ".x"],
        Some(&format!(r#"{{"x":{input}}}"#)),
    )?;
    assert_eq!(code, 0);
    assert_eq!(nested.trim(), input, "the printer gate is per-object");

    // Evaluation: jq's value model, flag or no flag.
    for (filter, expected) in [
        ("length", "2"),
        ("keys", r#"["a","b"]"#),
        ("[.[]]", "[3,2]"),
        ("to_entries|length", "2"),
    ] {
        let (out, _, code) = run_jq_full(&["-c", "--preserve-input", filter], Some(input))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    // The number spelling the flag exists for, split the same way.
    let (spelled, _, code) = run_jq_full(&["-c", "--preserve-input", ".n"], Some(r#"{"n":4e4}"#))?;
    assert_eq!(code, 0);
    assert_eq!(spelled.trim(), "4e4");
    let (evaluated, _, code) =
        run_jq_full(&["-c", "--preserve-input", ".n + 0"], Some(r#"{"n":4e4}"#))?;
    assert_eq!(code, 0);
    assert_eq!(evaluated.trim(), "40000");

    Ok(())
}

/// #1385 review: every `LazyKeys` arm in `eval_generic.rs`'s `Expr::Pipe`
/// dispatch answers differently once the object carries a duplicate, and
/// none of those answers was covered. Each filter here lands on a different
/// arm. (#1514 folded the separate `lazy_keys_collapsed` mirror this
/// originally covered back into the arms themselves; the filters are
/// unchanged because the answers are.)
#[test]
fn test_duplicate_keys_lazy_keys_fast_paths_1385() -> Result<()> {
    let input = r#"{"b":1,"a":2,"b":3}"#;
    let with_empty = r#"{"b":1,"a":2,"b":3,"n":{}}"#;
    for (filter, expected) in [
        ("keys_unsorted|length", "2"),            // Length
        ("[keys_unsorted[]]", r#"["b","a"]"#),    // Iterate
        ("keys_unsorted[0]", r#""b""#),           // Index, positive
        ("keys_unsorted[-1]", r#""a""#),          // Index, negative
        ("keys_unsorted[-9]", "null"),            // Index, out of range below
        ("keys_unsorted[9]", "null"),             // Index, out of range above
        ("keys_unsorted|first", r#""b""#),        // First
        ("keys_unsorted|last", r#""a""#),         // Last
        ("keys_unsorted|map(.)", r#"["b","a"]"#), // materializing fallback
        ("keys|length", "2"),                     // sorted: fallback, not the arms
        ("keys[0]", r#""a""#),
        // `first`/`last` wrapping the whole `keys` result forward the lazy
        // variant untouched rather than consuming it, so the collapse has
        // to survive that hop too.
        ("first(keys_unsorted)", r#"["b","a"]"#),
        ("last(keys_unsorted)", r#"["b","a"]"#),
        ("first(keys)", r#"["a","b"]"#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    // An empty nested object still prints as `{}` on the cursor path -- the
    // one object branch the collapse machinery must not reach -- and the
    // duplicate outside it is unaffected.
    for (filter, expected) in [
        (".n", "{}"),
        ("keys_unsorted|length", "3"),
        (".", r#"{"b":3,"a":2,"n":{}}"#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(with_empty))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }
    Ok(())
}

/// #1599: the `keys_unsorted` arms that no longer run a whole-object
/// `census` before answering -- `each_lazy_keys_iterate_sink` (which now
/// streams `DistinctKeyCursors` instead of collapsing-then-collecting) and
/// `fold_lazy_keys_stage`'s new `.[0]` arm.
///
/// **Reaching the streaming arm takes care.** It is used only for a
/// `.[]` stage driven by a *demand-aware* consumer, which in practice
/// means `first(...)`: `limit(n; ...)` does not route through it (its
/// elements arrive as owned strings, not cursors), and a collecting
/// `[keys_unsorted | .[]]` takes `fold_lazy_keys_stage`'s `Expr::Iterate`
/// arm instead. So only the `first(...)` rows below actually exercise the
/// rewrite; the others are here to pin that the *other* paths kept their
/// answers, which is the property that makes this a cost change.
///
/// The `select(...)` rows are the ones that matter most: a bare
/// `first(keys_unsorted | .[])` stops after a single element, so it never
/// reaches `DistinctKeyCursors`'s repeat handling at all. A predicate that
/// does not match until *after* the duplicate forces the walk through
/// `collapse_confirmed_repeat` and its resume-at-`yielded` path -- the one
/// branch of the rewrite that can reorder or drop a key if it is wrong.
///
/// Every expectation is jq 1.7.1's own output.
#[test]
fn test_lazy_keys_demand_sink_streams_collapse_1599() -> Result<()> {
    // Duplicate at the head: the very first key is the repeated one.
    let head = r#"{"b":1,"a":2,"b":3}"#;
    for (filter, expected) in [
        // -- reaches the streaming arm --
        ("first(keys_unsorted | .[])", r#""b""#),
        // Walks the whole object without matching: the repeat is reached
        // and resolved, and still nothing is emitted.
        ("[first(keys_unsorted | .[] | select(. == \"zzz\"))]", "[]"),
        // Matches only the key *after* the duplicate.
        ("first(keys_unsorted | .[] | select(. == \"a\"))", r#""a""#),
        // -- other paths, pinned to the same answers --
        ("[limit(2; keys_unsorted | .[])]", r#"["b","a"]"#),
        ("[limit(9; keys_unsorted | .[])]", r#"["b","a"]"#),
        ("[keys_unsorted | .[] | .]", r#"["b","a"]"#),
        // `.[0]`'s own no-census arm, and the neighbours that must keep
        // paying for one: a repeated key makes them differ.
        ("keys_unsorted | .[0]", r#""b""#),
        ("keys_unsorted | .[1]", r#""a""#),
        ("keys_unsorted | .[-1]", r#""a""#),
        ("keys_unsorted | .[9]", "null"),
        ("keys | .[0]", r#""a""#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(head))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    // Duplicate mid-stream: "a" repeats only as the fourth field, so a
    // consumer has already been handed three keys before the collapse is
    // discovered.
    let mid = r#"{"a":1,"b":2,"c":3,"a":4,"d":5}"#;
    for (filter, expected) in [
        ("first(keys_unsorted | .[])", r#""a""#),
        // Stops before the repeat is reached.
        ("first(keys_unsorted | .[] | select(. == \"b\"))", r#""b""#),
        // Lands exactly on the field that repeats.
        ("first(keys_unsorted | .[] | select(. == \"c\"))", r#""c""#),
        // Past it: this is the switch-and-resume branch. "d" is only
        // reachable by continuing correctly *through* the collapse.
        ("first(keys_unsorted | .[] | select(. == \"d\"))", r#""d""#),
        // Never matches, so the walk runs to completion through the repeat.
        ("[first(keys_unsorted | .[] | select(. == \"zzz\"))]", "[]"),
        // A downstream stage that actually transforms, so an empty or
        // dropped `rest` could not pass: the key is a string, not a number.
        ("first(keys_unsorted | .[] | length)", "1"),
        ("[keys_unsorted | .[] | .]", r#"["a","b","c","d"]"#),
        ("keys_unsorted | .[0]", r#""a""#),
        ("keys_unsorted | .[3]", r#""d""#),
        ("keys_unsorted | length", "4"),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(mid))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    // An empty object has no field 0, so the new `.[0]` arm's `uncons_key`
    // answers `None`. jq returns null rather than erroring here, same as
    // for an out-of-range index (#307).
    for (filter, expected) in [
        ("keys_unsorted | .[0]", "null"),
        ("keys_unsorted | first", "null"),
        ("keys_unsorted | .[1]", "null"),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some("{}"))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    // An uppercase key proves the trailing stage is really applied, which
    // a lowercase one could not: without `rest` the answer would be "B".
    let upper = r#"{"B":1,"a":2}"#;
    let (out, _, code) = run_jq_full(
        &["-c", "first(keys_unsorted | .[] | ascii_downcase)"],
        Some(upper),
    )?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), r#""b""#);

    Ok(())
}

/// #1599: the cursor a collapsed duplicate key reports moved, and this
/// pins where it landed.
///
/// The old collapse-then-collect path built its cursors from
/// `collapse_repeated`, which overwrites the surviving slot with the
/// *last* occurrence's `key_cursor`, so `first(keys_unsorted | .[] |
/// column)` on `{"b":1,"a":2,"b":3}` reported column 14 -- the second
/// `"b"`. Streaming emits the first occurrence, so it now reports 2.
///
/// 2 is the answer the collecting path (`[keys_unsorted | .[] | column]`
/// => `[2,8]`) has always given, so this removes a disagreement between
/// two spellings of the same query rather than introducing one; it is also
/// the position jq's own first-occurrence-wins rule points at. Recorded as
/// a deliberate change because the value is observable through the
/// position builtins (`column`/`line`) and through `anchor`/`style` in yq
/// mode, and nothing else pins it.
#[test]
fn test_lazy_keys_streaming_reports_first_occurrence_cursor_1599() -> Result<()> {
    let head = r#"{"b":1,"a":2,"b":3}"#;
    let (out, _, code) = run_jq_full(&["-c", "first(keys_unsorted | .[] | column)"], Some(head))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "2", "streamed cursor is the first occurrence");

    // The collecting path agrees, and always did.
    let (out, _, code) = run_jq_full(&["-c", "[keys_unsorted | .[] | column]"], Some(head))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "[2,8]");

    // `.[0]`'s no-census arm reports the same position.
    let (out, _, code) = run_jq_full(&["-c", "keys_unsorted | .[0] | column"], Some(head))?;
    assert_eq!(code, 0);
    assert_eq!(out.trim(), "2");

    Ok(())
}

/// #1598: the shapes that drive `continue_pipe_element_generic`'s `Owned`
/// arm, which now reads its owned copy of the remaining pipe from a
/// `RestPipe` cache instead of rebuilding one per element.
///
/// **What these do and do not prove.** They are a behavioural guard, not a
/// regression pin: every row below passes identically on the pre-change
/// binary, because the mispairing the cache could in principle suffer --
/// a cached pipe used with a `rest` it was not built from -- is not
/// expressible once `RestPipe` owns both halves as one value. That is the
/// real protection; these rows exist so that a future change widening the
/// cache's scope (sharing one across drivers, or hoisting it above a loop
/// that varies `rest`) fails visibly here rather than silently evaluating
/// elements against the wrong stages.
///
/// Reaching the arm at all takes care, so the rows are chosen to spread
/// across the drivers that get there, not just the convenient one:
///
/// - `keys` (sorted) yields each key as an owned string, driving
///   `each_lazy_keys_iterate_sink` -> `drive_pipe_elements_generic`. A
///   predicate that does not match keeps the driver pulling, so the loop
///   runs once per key rather than stopping at the first element.
/// - a bare comma stream (`(1,2,3) | f`) drives `eval_each_pipe_generic`'s
///   own closure, which carries the *second* cache the change adds -- the
///   `keys` rows leave it untouched, because stage 1 there hands back a
///   single `LazyKeys` item.
/// - `keys` over an array reaches `each_lazy_index_range_iterate_sink`,
///   and `map(f) | .[] | g` reaches `each_lazy_seq_iterate_sink`; both
///   land on the same cached arm by a different route.
///
/// Every expectation is jq 1.7.1's own output.
#[test]
fn test_pipe_element_rest_cache_across_drivers_1598() -> Result<()> {
    let object = r#"{"b":1,"a":2,"c":3}"#;
    for (filter, expected) in [
        // Never matches: walks every key through the `Owned` arm.
        (r#"[first(keys | .[] | select(. == "zzz"))]"#, "[]"),
        // Matches only the last key, so the loop runs to the end.
        (r#"first(keys | .[] | select(. == "c"))"#, r#""c""#),
        // Two drivers, different trailing pipes, in one program.
        (
            r#"[first(keys | .[] | select(. == "c")), first(keys | .[] | ascii_upcase)]"#,
            r#"["c","A"]"#,
        ),
        // Both trailing pipes multi-stage, differing in length and content.
        (
            r#"[first(keys | .[] | select(. == "c") | ascii_upcase), first(keys | .[] | select(. == "b"))]"#,
            r#"["C","b"]"#,
        ),
        // A longer trailing pipe: stage order must survive the caching.
        (
            r#"first(keys | .[] | tostring | select(. == "c") | ascii_upcase)"#,
            r#""C""#,
        ),
        // The non-`first` spelling, driving the arm without an early stop.
        (r#"[keys | .[] | select(. == "c")]"#, r#"["c"]"#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(object))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    // The other three drivers. `(1,2,3) | f` is the one that exercises
    // `eval_each_pipe_generic`'s own cache with more than one `Owned` item.
    let array = "[1,2,3]";
    for (filter, expected) in [
        (r"[(1,2,3) | tostring]", r#"["1","2","3"]"#),
        (r#"[("a","b") | ascii_upcase]"#, r#"["A","B"]"#),
        // Two comma-stream drivers with different trailing pipes.
        (
            r#"[first((1,2,3) | tostring), first(("x","y") | ascii_upcase)]"#,
            r#"["1","X"]"#,
        ),
        // `keys` over an array -> index-range driver, owned integer items.
        (r"[[10,20,30] | keys | .[] | . + 1]", "[1,2,3]"),
        // `map(f) | .[] | g` -> lazy-seq driver.
        (r"[map(.+1) | .[] | tostring]", r#"["2","3","4"]"#),
    ] {
        let (out, _, code) = run_jq_full(&["-c", filter], Some(array))?;
        assert_eq!(code, 0, "filter {filter}");
        assert_eq!(out.trim(), expected, "filter {filter}");
    }

    Ok(())
}

#[test]
fn test_jq_compat_default() -> Result<()> {
    // Test that jq-compat is now the default behavior
    // Numbers should be formatted like jq does (normalized scientific notation)
    let (output, code) = run_jq_stdin(".", r#"{"val":4e4}"#, &["-c"])?;
    assert_eq!(code, 0);
    // Default jq-compat normalizes 4e4 to 4E+4 (like jq)
    assert_eq!(output.trim(), r#"{"val":4E+4}"#);
    Ok(())
}

#[test]
fn test_large_integer_literal_prints_like_jq() -> Result<()> {
    // Integer literals beyond i64 degrade to floats *numerically* (issue
    // #166), but #1035 keeps the literal's own source spelling through
    // evaluation, matching real jq: `jq -n '9999999999999999999'` prints
    // the digit string back verbatim, not a rounded
    // `10000000000000000000` (verified against jq 1.7.1 -- the comment
    // this test previously carried claiming otherwise was never actually
    // checked against a live oracle).
    let (output, code) = run_jq_stdin("9999999999999999999", "null", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), "9999999999999999999");
    Ok(())
}

#[test]
fn test_args_positional() -> Result<()> {
    // Test --args: positional args become $ARGS.positional
    // Note: Use pipe syntax since parser doesn't support $VAR.field directly
    let (output, _code) = spawn_jq(
        &[
            "-n",
            "-c",
            "$ARGS | .positional",
            "--args",
            "hello",
            "world",
        ],
        None,
    )?;
    let stdout = String::from_utf8(output.stdout)?;
    assert_eq!(stdout.trim(), r#"["hello","world"]"#);
    Ok(())
}

