#[test]
fn test_no_color_env_var() -> Result<()> {
    // Test that NO_COLOR environment variable disables color output
    // When NO_COLOR is set and no explicit -C/-M flag is given, colors should be disabled.
    let (result, _code) = spawn_jq_with_env(
        &["."], // No -C or -M flag
        "NO_COLOR",
        "1",
        Some(b"{\"a\":1}"),
    )?;
    let stdout = String::from_utf8(result.stdout)?;

    // Without -C flag and with NO_COLOR set, output should not contain ANSI codes
    assert!(
        !stdout.contains("\x1b["),
        "Output should not contain ANSI escape codes when NO_COLOR is set"
    );
    Ok(())
}

#[test]
fn test_jq_colors_env_var() -> Result<()> {
    // Test that JQ_COLORS environment variable customizes colors
    // Format: "null:false:true:numbers:strings:arrays:objects:objectkeys"
    // Use a distinctive color for null (red = 31) to verify it works
    let (output, _code) = spawn_jq_with_env(
        &["-C", "-n", "null"], // Force color output
        "JQ_COLORS",
        "0;31:::::::", // Red null, defaults for rest
        None,
    )?;

    let stdout = String::from_utf8(output.stdout)?;
    // Check that the red color code (31) is present for null
    assert!(
        stdout.contains("\x1b[0;31m"),
        "Output should contain custom red color for null"
    );
    Ok(())
}

#[test]
fn test_color_output_overrides_no_color() -> Result<()> {
    // Test that -C flag overrides NO_COLOR env var
    let (output, _code) = spawn_jq_with_env(
        &["-C", "-n", r#"{"a":1}"#], // Force color
        "NO_COLOR",
        "1", // This should be overridden by -C
        None,
    )?;

    let stdout = String::from_utf8(output.stdout)?;
    // -C should force colors even with NO_COLOR set
    assert!(
        stdout.contains("\x1b["),
        "Output should contain ANSI codes when -C is used"
    );
    Ok(())
}

#[test]
fn test_monochrome_overrides_jq_colors() -> Result<()> {
    // Test that -M flag disables colors even if JQ_COLORS is set
    let (output, _code) = spawn_jq_with_env(
        &["-M", "-n", r#"{"a":1}"#], // Monochrome output
        "JQ_COLORS",
        "0;31:0;32:0;33:0;34:0;35:0;36:0;37:0;38",
        None,
    )?;

    let stdout = String::from_utf8(output.stdout)?;
    // -M should disable all colors
    assert!(
        !stdout.contains("\x1b["),
        "Output should not contain ANSI codes when -M is used"
    );
    Ok(())
}

#[test]
fn test_jq_colors_invalid_spec_warns_and_uses_defaults() -> Result<()> {
    // A malformed JQ_COLORS spec is rejected as a whole: jq warns on stderr,
    // falls back to the default scheme, and still exits successfully.
    let (output, code) = spawn_jq_with_env(&["-C", "-n", "null"], "JQ_COLORS", "bogus", None)?;

    assert_eq!(code, 0);
    let stderr = String::from_utf8(output.stderr)?;
    assert!(
        stderr.contains("Failed to set $JQ_COLORS"),
        "expected warning on stderr: {stderr:?}"
    );
    let stdout = String::from_utf8(output.stdout)?;
    assert!(
        stdout.contains("\x1b[1;30mnull\x1b[0m"),
        "null should use the default color: {stdout:?}"
    );
    Ok(())
}

#[test]
fn test_color_output_materializes_cursor_values() -> Result<()> {
    // A non-identity filter yields a cursor result; with -C it must take the
    // materialize-and-colorize path rather than the streaming printer.
    let (output, code) = run_jq_stdin(".a", r#"{"a":[1,false]}"#, &["-c", "-C"])?;
    assert_eq!(code, 0);
    assert_eq!(
        output.trim(),
        // #3110: the `,` is wrapped in the enclosing container's color
        // (array `1;39` here), matching real jq.
        "\x1b[1;39m[\x1b[0m\x1b[0;39m1\x1b[0m\x1b[1;39m,\x1b[0m\x1b[0;39mfalse\x1b[0m\x1b[1;39m]\x1b[0m"
    );
    Ok(())
}

/// #3110: `-C -c` object output must color-wrap the `:` key/value separator
/// in the object color, and the `,` in its enclosing container's color,
/// as real jq does. Byte-pinned against jq 1.7.1 (this exact invocation
/// and input); the only intentional byte difference from real jq is that
/// succinctly emits one SGR per token where jq redundantly repeats the
/// SGR before a closing delimiter (visually identical -- see
/// docs/compliance/jq/limitations.md).
#[test]
fn test_color_compact_wraps_object_separator_3110() -> Result<()> {
    // The issue's own example.
    let (output, code) = run_jq_stdin(".", r#"{"a":1,"b":2}"#, &["-C", "-c"])?;
    assert_eq!(code, 0);
    assert_eq!(
        output.trim(),
        "\x1b[1;39m{\x1b[0m\x1b[1;34m\"a\"\x1b[0m\x1b[1;39m:\x1b[0m\x1b[0;39m1\x1b[0m\
         \x1b[1;39m,\x1b[0m\x1b[1;34m\"b\"\x1b[0m\x1b[1;39m:\x1b[0m\x1b[0;39m2\x1b[0m\
         \x1b[1;39m}\x1b[0m"
    );

    // Nested: the `:` inside an object that lives in an array is still the
    // object color; the enclosing `,` is the array color.
    let (output, code) = run_jq_stdin(".", r#"[{"a":1},2]"#, &["-C", "-c"])?;
    assert_eq!(code, 0);
    assert_eq!(
        output.trim(),
        "\x1b[1;39m[\x1b[0m\x1b[1;39m{\x1b[0m\x1b[1;34m\"a\"\x1b[0m\x1b[1;39m:\x1b[0m\
         \x1b[0;39m1\x1b[0m\x1b[1;39m}\x1b[0m\x1b[1;39m,\x1b[0m\x1b[0;39m2\x1b[0m\
         \x1b[1;39m]\x1b[0m"
    );
    Ok(())
}

